/**
 * The rules and scan pane, drawn from plain data and handler closures. Values
 * appear here only, on this screen; they never reach the model. Masked unless
 * the person asks to show them.
 */
import type { Elements } from 'claude-code';
import { CUSTOM_LABEL, SESSION_PLACEHOLDER_LIMIT } from './defaults.ts';
import type { Metrics } from './metrics.ts';
import { describePatternProblem, patternDetector, patternProblem, type PatternRule } from './patterns.ts';
import { LABEL_PATTERN, type PlaceholderScheme, type ValueRule } from './placeholder.ts';
import { maskPreview, type RuleProblem, type StoredPattern, type StoredRule } from './rules.ts';
import type { ScanCandidate } from './scan.ts';
import type { StatusStats } from './status.ts';

export type PaneTab = 'rules' | 'scan' | 'session' | 'test';

/** The Test tab's result: computed on this machine, never recorded in the session or sent anywhere. */
export interface TestView {
  readonly text: string;
  /** The text as the model would receive it. */
  readonly masked: string;
  /** Each value found, once, in order: its label and the original. */
  readonly found: ReadonlyArray<{ readonly label: string; readonly value: string }>;
}

/** One placeholder this session minted, and the value it stands for (shown masked unless revealed). */
export interface SessionEntry {
  readonly placeholder: string;
  readonly label: string;
  readonly value: string;
}

/** The current session, as counts and the placeholders it made. */
export interface SessionView {
  readonly stats: StatusStats;
  readonly metrics: Metrics;
  readonly byLabel: ReadonlyArray<readonly [string, number]>;
  /** The newest placeholders, oldest first. */
  readonly entries: readonly SessionEntry[];
  readonly total: number;
  readonly placeholderFormat: string;
  readonly detectors: number;
  readonly savedRules: number;
  readonly optionRules: number;
}

/** Builds the session view from the vault (placeholder to value) and the counters. */
export function sessionView(
  vault: Readonly<Record<string, string>>,
  metrics: Metrics,
  stats: StatusStats,
  scheme: PlaceholderScheme,
  counts: { detectors: number; savedRules: number; optionRules: number },
): SessionView {
  const all = Object.entries(vault).map(([placeholder, value]) => ({
    placeholder,
    value,
    label: scheme.labelOf(placeholder) ?? 'ALIAS',
  }));
  const byLabel = new Map<string, number>();
  for (const entry of all) byLabel.set(entry.label, (byLabel.get(entry.label) ?? 0) + 1);
  return {
    stats,
    metrics,
    byLabel: [...byLabel.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
    entries: all.slice(-SESSION_PLACEHOLDER_LIMIT),
    total: all.length,
    placeholderFormat: scheme.format,
    ...counts,
  };
}

/** `Bash 2, Write 1`, or `none`. */
function tally(counts: Readonly<Record<string, number>> | ReadonlyArray<readonly [string, number]>): string {
  const pairs = Array.isArray(counts) ? counts : Object.entries(counts).sort((a, b) => b[1] - a[1]);
  return pairs.length ? pairs.map(([name, count]) => `${name} ${count}`).join(' · ') : 'none';
}

function clock(ms: number): string {
  if (!ms) return '—';
  const at = new Date(ms);
  return `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`;
}

export type DraftMode = 'label' | 'alias';

/** The rule form: what the person has typed and picked so far (this screen only). */
export type DraftKind = 'value' | 'pattern';
export type DraftCase = 'default' | 'yes' | 'no';

export interface RuleDraft {
  /** An exact value, or a pattern (regex). */
  readonly kind: DraftKind;
  readonly value: string;
  readonly mode: DraftMode;
  readonly label: string;
  /** True when the label is typed rather than picked from the list. */
  readonly customLabel: boolean;
  readonly alias: string;
  /** The form was filled from a saved rule; saving updates it. */
  readonly editing: boolean;
  /** Ignore case: follow the `custom_case_insensitive` option, or yes / no for this rule. */
  readonly ignoreCase: DraftCase;
  readonly pattern: string;
  readonly wholeWord: boolean;
  /** 0 masks the whole match; N masks capture group N. */
  readonly group: number;
  /** A sample the pattern must match; checked on save, never stored. */
  readonly example: string;
  /** What the value is, told to the model ("client company name"); optional. */
  readonly description: string;
}

export const EMPTY_DRAFT: RuleDraft = {
  kind: 'value',
  ignoreCase: 'default',
  pattern: '',
  wholeWord: true,
  group: 0,
  example: '',
  description: '',
  value: '',
  mode: 'label',
  label: CUSTOM_LABEL,
  customLabel: false,
  alias: '',
  editing: false,
};

export interface PaneView {
  readonly view: PaneTab;
  readonly reveal: boolean;
  readonly notice: string;
  readonly draft: RuleDraft;
  readonly test?: TestView;
}

export interface ScanView {
  readonly candidates: readonly ScanCandidate[];
  /** Found values a rule, the email scanner or a detector already masks. */
  readonly covered: number;
  /** Found values dismissed before. */
  readonly ignored: number;
  /** A path scan: the folder or file as shown (`~/…`), files read, and values already masked by label. */
  readonly target?: string;
  readonly files?: number;
  /** Files a path scan looked at but left out: binary, too large or unreadable. */
  readonly skipped?: number;
  /** A path scan stopped before the end of the tree (file, folder or depth limit). */
  readonly partial?: boolean;
  readonly kinds?: ReadonlyArray<readonly [string, number]>;
}

export interface PaneData {
  readonly view: PaneView;
  readonly stored: readonly StoredRule[];
  /** Rules from the plugin options (keychain): shown, never edited here. */
  readonly optionRules: readonly ValueRule[];
  readonly scan: ScanView | null;
  readonly session: SessionView;
  /** False where the surface has no text field (mobile). */
  readonly canType: boolean;
  /** A sample placeholder for a label, in the active format. */
  readonly example: (label: string) => string;
  /** Labels offered in the rule form (see `formLabels`). */
  readonly labels: readonly string[];
  readonly patterns: readonly StoredPattern[];
  /** Patterns from the plugin options (keychain), counted only. */
  readonly optionPatterns: number;
  /** The `custom_case_insensitive` option: what "Follow the option" means. */
  readonly caseDefault: boolean;
}

export interface PaneActions {
  show(view: PaneTab): void;
  toggleReveal(): void;
  setDraft(change: Partial<RuleDraft>): void;
  /** Saves the form; `patch` is a field's latest text when Enter submitted it. */
  saveDraft(patch?: Partial<RuleDraft>): void;
  clearDraft(): void;
  edit(rule: StoredRule): void;
  remove(value: string): void;
  removePattern(pattern: StoredPattern): void;
  scan(): void;
  accept(candidate: ScanCandidate): void;
  acceptAll(): void;
  ignore(candidate: ScanCandidate): void;
  close(): void;
  /** Checks text in the Test tab; empty clears it. */
  test(text: string): void;
}

export type PaneElements = Pick<Elements['desktop'], 'Box' | 'Text' | 'Button'> & {
  readonly Input?: Elements['desktop']['Input'];
  readonly Select?: Elements['desktop']['Select'];
};

export const EMPTY_VIEW: PaneView = { view: 'rules', reveal: false, notice: '', draft: EMPTY_DRAFT };

const OTHER_LABEL = '__other';

/** What is missing or wrong in the form before it can be saved (the full check runs on save). */
export function draftProblem(draft: RuleDraft): RuleProblem | undefined {
  if (draft.kind === 'pattern') {
    const label = draft.label.trim();
    if (!label) return 'no-label';
    return LABEL_PATTERN.test(label) ? undefined : 'invalid-label';
  }
  if (!draft.value.trim()) return 'empty';
  if (draft.mode === 'alias') return draft.alias.trim() ? undefined : 'no-alias';
  const label = draft.label.trim();
  if (!label) return 'no-label';
  return LABEL_PATTERN.test(label) ? undefined : 'invalid-label';
}

/** The pattern rule the form describes; `caseDefault` is the `custom_case_insensitive` option. */
export function draftPattern(draft: RuleDraft, caseDefault: boolean): PatternRule {
  const label = draft.label.trim().toUpperCase();
  return {
    pattern: draft.pattern.trim(),
    ...(label && label !== CUSTOM_LABEL ? { label } : {}),
    ignoreCase: draft.ignoreCase === 'default' ? caseDefault : draft.ignoreCase === 'yes',
    wholeWord: draft.wholeWord,
    group: draft.group,
    example: draft.example,
    ...(draft.description.trim() ? { description: draft.description.trim() } : {}),
  };
}

/** A pattern's example as the model would see it, or why the pattern cannot be saved yet. */
export function patternPreview(draft: RuleDraft, caseDefault: boolean, example: (label: string) => string): string {
  if (!draft.pattern.trim()) return '(type a pattern and an example it must match)';
  const rule = draftPattern(draft, caseDefault);
  const problem = patternProblem(rule);
  if (problem) return `(${describePatternProblem(problem)})`;
  const spans = patternDetector(rule, 'preview').find(draft.example);
  let text = draft.example;
  for (const { start, end } of [...spans].reverse()) {
    text = `${text.slice(0, start)}${example(rule.label ?? CUSTOM_LABEL)}${text.slice(end)}`;
  }
  return text;
}

/** What the model would see for the form as filled in. */
export function draftPreview(draft: RuleDraft, example: (label: string) => string): string {
  if (draft.mode === 'alias') return draft.alias.trim() || '(type an alias)';
  const label = draft.label.trim().toUpperCase();
  if (!label) return '(type a label)';
  return LABEL_PATTERN.test(label) ? example(label) : '(not a valid label)';
}

/** The form's label list: CUSTOM, the configured labels, then every label a rule already uses. */
export function formLabels(configured: readonly string[], rules: ReadonlyArray<Pick<ValueRule, 'label'>>): string[] {
  const used = rules.flatMap(rule => (rule.label ? [rule.label] : []));
  return [...new Set([CUSTOM_LABEL, ...configured, ...used])];
}

/** The form filled from a saved rule, for editing its label or alias. */
export function draftFrom(
  rule: Pick<StoredRule, 'value' | 'label' | 'alias' | 'ignoreCase' | 'description'>,
  labels: readonly string[],
): RuleDraft {
  const label = rule.label ?? CUSTOM_LABEL;
  return {
    ...EMPTY_DRAFT,
    ignoreCase: rule.ignoreCase === undefined ? 'default' : rule.ignoreCase ? 'yes' : 'no',
    value: rule.value,
    mode: rule.alias ? 'alias' : 'label',
    label,
    customLabel: !labels.includes(label),
    alias: rule.alias ?? '',
    description: rule.description ?? '',
    editing: true,
  };
}

function tag(rule: Pick<StoredRule, 'label' | 'alias'>): string {
  if (rule.alias) return `alias ${rule.alias}`;
  return rule.label ?? 'CUSTOM';
}

export function drawPane(ui: PaneElements, data: PaneData, act: PaneActions) {
  const { Box, Text, Button, Input, Select } = ui;
  const draft: RuleDraft = { ...EMPTY_DRAFT, ...data.view.draft };
  const shown = (value: string) => (data.view.reveal ? value : maskPreview(value));
  const tab = data.view.view;

  const header = (
    <Box flexDirection="row" gap={1} flexWrap="wrap">
      <Button key="tab-rules" variant={tab === 'rules' ? 'primary' : 'secondary'} onPress={() => act.show('rules')}>
        Rules
      </Button>
      <Button key="tab-scan" variant={tab === 'scan' ? 'primary' : 'secondary'} onPress={() => act.show('scan')}>
        Scan
      </Button>
      <Button
        key="tab-session"
        variant={tab === 'session' ? 'primary' : 'secondary'}
        onPress={() => act.show('session')}
      >
        Session
      </Button>
      <Button key="tab-test" variant={tab === 'test' ? 'primary' : 'secondary'} onPress={() => act.show('test')}>
        Test
      </Button>
      <Button key="reveal" onPress={() => act.toggleReveal()}>
        {data.view.reveal ? 'Hide values' : 'Show values'}
      </Button>
      <Button key="close" role="dismiss" onPress={() => act.close()}>
        Close
      </Button>
    </Box>
  );

  const notice = data.view.notice ? <Text bold>{data.view.notice}</Text> : null;

  if (tab === 'test') {
    const result = data.view.test;
    return (
      <Box flexDirection="column" gap={1}>
        {header}
        {notice}
        <Text dimColor>
          Paste text to see what the model would receive. It is checked on this machine: nothing is sent, saved or added
          to the session.
        </Text>
        {data.canType && Input ? (
          <Input
            key="test-input"
            label="Text to check"
            placeholder="Paste a log, config or message"
            submitLabel="check"
            autoFocus
            onSubmit={text => act.test(text)}
          />
        ) : (
          <Text dimColor>Testing text needs the terminal or the desktop app.</Text>
        )}
        {result ? (
          <Box flexDirection="column" gap={1}>
            <Box flexDirection="column">
              <Text bold>The model would see</Text>
              <Text>{result.masked}</Text>
            </Box>
            <Box flexDirection="column">
              <Text bold>
                {result.found.length === 0
                  ? 'Nothing found: this text would be sent as it is.'
                  : `${result.found.length} value(s) found`}
              </Text>
              {result.found.map((item, index) => (
                <Box key={`found-${index}`} flexDirection="row" gap={1} flexWrap="wrap">
                  <Text dimColor>{item.label}</Text>
                  <Text>{shown(item.value)}</Text>
                </Box>
              ))}
              {result.found.length === 0 ? (
                <Text dimColor>Something private in it? Add it as a rule on the Rules tab.</Text>
              ) : null}
            </Box>
            <Button key="test-clear" onPress={() => act.test('')}>
              Clear
            </Button>
          </Box>
        ) : null}
      </Box>
    );
  }

  if (tab === 'session') {
    const { stats, metrics: m } = data.session;
    const row = (name: string, text: string, key: string) => (
      <Box key={key} flexDirection="row" gap={1}>
        <Box width={10} flexShrink={0}>
          <Text bold>{name}</Text>
        </Box>
        <Text>{text}</Text>
      </Box>
    );
    const errors = Object.values(m.hookErrors).reduce((sum, count) => sum + count, 0);
    const block = m.lastBlock
      ? ` · last block: ${m.lastBlock.kind}${m.lastBlock.block ? ` in ${m.lastBlock.block}` : ''}`
      : '';
    return (
      <Box flexDirection="column" gap={1}>
        {header}
        {notice}
        <Box flexDirection="column">
          {row(
            'State',
            `${stats.state} · since ${clock(m.startedAt)} · last ${m.lastEvent} at ${clock(m.updatedAt)}`,
            's-state',
          )}
          {row(
            'Masked',
            `${stats.masked} values · ${stats.occurrences} replacements · ${stats.lastTurn} since last prompt`,
            's-masked',
          )}
          {row('Kinds', tally(data.session.byLabel), 's-kinds')}
          {row('Sources', tally(m.bySource), 's-sources')}
          {row(
            'Tools',
            `restored ${m.restoredCalls} (${tally(m.restoredByTool)}) · kept ${m.keptCalls} · denied ${m.deniedCalls}`,
            's-tools',
          )}
          {row('Requests', `audited ${m.audits} · blocked ${m.blocked}${block}`, 's-requests')}
          {row(
            'Other',
            `media withheld ${m.mediaWithheld} · prompts refused ${m.promptsDropped} · hook errors ${errors}${errors ? ` (${tally(m.hookErrors)})` : ''}`,
            's-other',
          )}
          {row(
            'Settings',
            `restore ${stats.mode} · audit ${stats.audit ? 'on' : 'off'} · streaming ${stats.streaming ? 'on' : 'off'} · ` +
              `${data.session.detectors} detectors · rules ${data.session.savedRules} saved + ${data.session.optionRules} options`,
            's-settings',
          )}
          {row('Format', data.session.placeholderFormat, 's-format')}
        </Box>
        <Box flexDirection="column">
          <Text bold>
            Placeholders ({data.session.total}
            {data.session.total > data.session.entries.length ? `, newest ${data.session.entries.length}` : ''})
          </Text>
          {data.session.total === 0 ? <Text dimColor>Nothing masked yet in this session.</Text> : null}
          {data.session.entries.map((entry, index) => (
            <Box key={`placeholder-${index}`} flexDirection="row" gap={1} flexWrap="wrap">
              <Text>{entry.placeholder}</Text>
              <Text dimColor>{shown(entry.value)}</Text>
            </Box>
          ))}
        </Box>
      </Box>
    );
  }

  if (tab === 'scan') {
    const scan = data.scan;
    return (
      <Box flexDirection="column" gap={1}>
        {header}
        {notice}
        {scan === null ? (
          <Box flexDirection="column">
            <Text>
              Scan looks at the git identity, remotes and recent authors, this computer's name, your account name, .env
              files and the package author; /redact-restore scan PATH checks a folder or file. Everything runs on this
              machine, and results stay in this pane.
            </Text>
            <Button key="scan-run" variant="primary" onPress={() => act.scan()}>
              Scan now
            </Button>
          </Box>
        ) : (
          <Box flexDirection="column">
            {scan.target ? (
              <Text dimColor>
                {scan.target} · {scan.files ?? 0} file(s) read
              </Text>
            ) : null}
            <Text dimColor>
              {scan.candidates.length} new · {scan.covered} already masked · {scan.ignored} ignored before
            </Text>
            {scan.kinds && scan.kinds.length > 0 ? (
              <Text dimColor>Already masked in these files: {tally(scan.kinds)}</Text>
            ) : null}
            <Box flexDirection="row" gap={1}>
              <Button key="scan-again" onPress={() => act.scan()}>
                Scan again
              </Button>
              {scan.candidates.length > 0 ? (
                <Button key="scan-all" variant="primary" onPress={() => act.acceptAll()}>
                  Add all
                </Button>
              ) : null}
            </Box>
            {scan.candidates.map((candidate, index) => (
              <Box key={`candidate-${index}`} flexDirection="row" gap={1} flexWrap="wrap">
                <Text>{shown(candidate.value)}</Text>
                <Text dimColor>
                  {candidate.label} · {candidate.source}
                </Text>
                <Button key={`accept-${index}`} onPress={() => act.accept(candidate)}>
                  Add
                </Button>
                <Button key={`ignore-${index}`} onPress={() => act.ignore(candidate)}>
                  Ignore
                </Button>
              </Box>
            ))}
          </Box>
        )}
      </Box>
    );
  }

  return (
    <Box flexDirection="column" gap={1}>
      {header}
      {notice}
      {data.canType && Input && Select ? (
        <Box key="form" flexDirection="column" borderStyle="round" paddingX={1}>
          <Text bold>{draft.editing ? 'Edit rule' : 'Add a rule'}</Text>
          {draft.editing ? null : (
            <Select
              key="draft-kind"
              label="Rule type"
              value={draft.kind}
              options={[
                { value: 'value', label: 'Exact value' },
                { value: 'pattern', label: 'Pattern (regular expression)' },
              ]}
              onSelect={kind => act.setDraft({ kind: kind === 'pattern' ? 'pattern' : 'value' })}
            />
          )}
          {draft.kind === 'pattern' ? (
            <Input
              key="draft-pattern"
              label="Pattern"
              placeholder="e.g. ACME-[A-Z0-9]{16}"
              value={draft.pattern}
              autoFocus
              onInput={pattern => act.setDraft({ pattern })}
              onSubmit={pattern => act.setDraft({ pattern })}
            />
          ) : draft.editing ? (
            <Box flexDirection="row" gap={1}>
              <Text>Private value:</Text>
              <Text>{shown(draft.value)}</Text>
              <Text dimColor>(fixed while editing; remove the rule to change it)</Text>
            </Box>
          ) : (
            <Input
              key="draft-value"
              label="Private value"
              placeholder="e.g. Acme Corp"
              value={draft.value}
              submitLabel="save"
              autoFocus
              onInput={value => act.setDraft({ value })}
              onSubmit={value => act.saveDraft({ value })}
            />
          )}
          {draft.kind === 'pattern' ? (
            <Input
              key="draft-example"
              label="Example it must match"
              placeholder="a made-up sample, e.g. ACME-0000AAAA1111BBBB"
              value={draft.example}
              submitLabel="save"
              onInput={example => act.setDraft({ example })}
              onSubmit={example => act.saveDraft({ example })}
            />
          ) : (
            <Select
              key="draft-mode"
              label="Replace with"
              value={draft.mode}
              options={[
                { value: 'label', label: 'Placeholder with a label' },
                { value: 'alias', label: 'Fixed alias' },
              ]}
              onSelect={mode => act.setDraft({ mode: mode === 'alias' ? 'alias' : 'label' })}
            />
          )}
          {draft.kind === 'pattern' || draft.mode === 'label' ? (
            <Select
              key="draft-label"
              label="Label"
              value={draft.customLabel ? OTHER_LABEL : draft.label}
              options={[
                ...data.labels.map(label => ({ value: label, label })),
                { value: OTHER_LABEL, label: 'Other label…' },
              ]}
              onSelect={label =>
                act.setDraft(label === OTHER_LABEL ? { customLabel: true, label: '' } : { customLabel: false, label })
              }
            />
          ) : (
            <Input
              key="draft-alias"
              label="Alias"
              placeholder="e.g. CLIENT_A"
              value={draft.alias}
              submitLabel="save"
              onInput={alias => act.setDraft({ alias })}
              onSubmit={alias => act.saveDraft({ alias })}
            />
          )}
          {(draft.kind === 'pattern' || draft.mode === 'label') && draft.customLabel ? (
            <Input
              key="draft-custom-label"
              label="Custom label"
              placeholder="e.g. VENDOR"
              value={draft.label}
              submitLabel="save"
              onInput={label => act.setDraft({ label })}
              onSubmit={label => act.saveDraft({ label })}
            />
          ) : null}
          <Input
            key="draft-description"
            label="Description for the model (optional)"
            placeholder="what it is, not the value: e.g. client company name"
            value={draft.description}
            submitLabel="save"
            onInput={description => act.setDraft({ description })}
            onSubmit={description => act.saveDraft({ description })}
          />
          <Select
            key="draft-case"
            label="Ignore case"
            value={draft.ignoreCase}
            options={[
              { value: 'default', label: `Follow the option (${data.caseDefault ? 'yes' : 'no'})` },
              { value: 'yes', label: 'Yes' },
              { value: 'no', label: 'No' },
            ]}
            onSelect={ignoreCase =>
              act.setDraft({ ignoreCase: ignoreCase === 'yes' ? 'yes' : ignoreCase === 'no' ? 'no' : 'default' })
            }
          />
          {draft.kind === 'pattern' ? (
            <Select
              key="draft-whole"
              label="Whole word"
              value={draft.wholeWord ? 'yes' : 'no'}
              options={[
                { value: 'yes', label: 'Yes: no letter or digit touching either end' },
                { value: 'no', label: 'No: match inside longer text too' },
              ]}
              onSelect={whole => act.setDraft({ wholeWord: whole !== 'no' })}
            />
          ) : null}
          {draft.kind === 'pattern' ? (
            <Select
              key="draft-group"
              label="Mask"
              value={String(draft.group)}
              options={[
                { value: '0', label: 'The whole match' },
                { value: '1', label: 'Capture group 1 only' },
                { value: '2', label: 'Capture group 2 only' },
                { value: '3', label: 'Capture group 3 only' },
              ]}
              onSelect={group => act.setDraft({ group: Number(group) || 0 })}
            />
          ) : null}
          <Text dimColor>
            The model sees:{' '}
            {draft.kind === 'pattern'
              ? patternPreview(draft, data.caseDefault, data.example)
              : draftPreview(draft, data.example)}
            {draft.description.trim() ? `, described as "${draft.description.trim()}"` : ''}
          </Text>
          <Box flexDirection="row" gap={1}>
            <Button key="draft-save" variant="primary" onPress={() => act.saveDraft()}>
              {draft.editing ? 'Save rule' : 'Add rule'}
            </Button>
            <Button key="draft-clear" onPress={() => act.clearDraft()}>
              Clear
            </Button>
          </Box>
        </Box>
      ) : (
        <Text dimColor>Adding rules needs the terminal or the desktop app.</Text>
      )}
      <Box flexDirection="column">
        <Text bold>Saved rules ({data.stored.length}) · plugin store, takes effect now</Text>
        {data.stored.length === 0 ? <Text dimColor>None yet. Add one above, or use Scan.</Text> : null}
        {data.stored.map((rule, index) => (
          <Box key={`rule-${index}`} flexDirection="row" gap={1} flexWrap="wrap">
            <Text>{shown(rule.value)}</Text>
            <Text dimColor>
              {tag(rule)} · {rule.source}
              {rule.description ? ` · "${rule.description}"` : ''}
            </Text>
            {data.canType ? (
              <Button key={`edit-${index}`} onPress={() => act.edit(rule)}>
                Edit
              </Button>
            ) : null}
            <Button key={`remove-${index}`} onPress={() => act.remove(rule.value)}>
              Remove
            </Button>
          </Box>
        ))}
      </Box>
      <Box flexDirection="column">
        <Text bold>Saved patterns ({data.patterns.length}) · plugin store, takes effect now</Text>
        {data.patterns.length === 0 ? <Text dimColor>None yet. Pick Pattern as the rule type to add one.</Text> : null}
        {data.patterns.map((pattern, index) => (
          <Box key={`pattern-${index}`} flexDirection="row" gap={1} flexWrap="wrap">
            <Text>/{pattern.pattern}/</Text>
            <Text dimColor>
              {pattern.label ?? CUSTOM_LABEL}
              {pattern.ignoreCase ? ' · ignore case' : ''}
              {pattern.wholeWord ? ' · whole word' : ''}
              {pattern.group ? ` · group ${pattern.group}` : ''} · {pattern.source}
              {pattern.description ? ` · "${pattern.description}"` : ''}
            </Text>
            <Button key={`remove-pattern-${index}`} onPress={() => act.removePattern(pattern)}>
              Remove
            </Button>
          </Box>
        ))}
      </Box>
      <Box flexDirection="column">
        <Text bold>
          Plugin options ({data.optionRules.length}
          {data.optionPatterns ? ` values, ${data.optionPatterns} patterns` : ''}) · keychain, edit in /plugin
        </Text>
        {data.optionRules.map((rule, index) => (
          <Box key={`option-${index}`} flexDirection="row" gap={1}>
            <Text>{shown(rule.value)}</Text>
            <Text dimColor>{tag(rule)}</Text>
          </Box>
        ))}
      </Box>
    </Box>
  );
}

files.hooks/placeholder.ts:
/**
 * How placeholders look. Pure: a scheme is built once from the options and
 * passed to the matcher, the masker and the restorers.
 *
 * A format is literal text with `{label}` and `{id}` fields. The default,
 * `{{PRIVATE:{label}#{id}}}` (e.g. `{{PRIVATE:EMAIL#3fa1c09e8b2d}}`), is easy for models to
 * copy and has no shell glob or redirect characters; it is also template
 * syntax (Jinja, Handlebars, Actions) and needs quoting in YAML, which matters
 * only where a tool receives placeholders unrestored. A format must
 * start with literal text and contain no whitespace, so a placeholder can be
 * found in running text and recognized while it streams in pieces; it ends
 * with literal text or with the fixed-length `{id}`.
 */
import { hmacSha256Hex } from './hmac.ts';
import {
  CUSTOM_LABEL,
  DEFAULT_FORMAT,
  DESCRIPTION_LIMITS,
  DEFAULT_ID_LENGTH,
  EMAIL_LABEL,
  ID_KEY_BYTES,
  MAX_ID_LENGTH,
  MIN_ID_LENGTH,
} from './defaults.ts';

export { CUSTOM_LABEL, DEFAULT_FORMAT, DEFAULT_ID_LENGTH, EMAIL_LABEL, MAX_ID_LENGTH, MIN_ID_LENGTH };

/** Labels a user may give a value: letters, digits, underscore. */
export const LABEL_PATTERN = /^[A-Za-z][A-Za-z0-9_]{0,31}$/;

export interface PlaceholderScheme {
  readonly format: string;
  readonly idLength: number;
  /**
   * A placeholder for a label. With a stable-id key and a value, the id is
   * derived from both, so the value gets the same placeholder in every session;
   * otherwise it is random.
   */
  make(label: string, value?: string): string;
  /** Whether ids are derived from values (`placeholder_ids: stable`) and the key is loaded. */
  readonly stableIds: boolean;
  /** Every placeholder of this format (global regex; reset `lastIndex` yourself). */
  readonly pattern: RegExp;
  /** The label inside a placeholder of this format, or undefined. */
  labelOf(token: string): string | undefined;
  /** Where to stop emitting streamed text so a split placeholder waits whole. */
  holdPoint(text: string): number;
  /** An example for the model note: `{{PRIVATE:EMAIL#<id>}}`. */
  example(label: string): string;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Why a format cannot be used, or undefined when it can. */
export function formatProblem(format: string): string | undefined {
  if (format.length > 80) return 'is longer than 80 characters';
  if (/\s/.test(format)) return 'contains whitespace';
  if (format.split('{id}').length !== 2) return 'must contain {id} exactly once';
  if (format.split('{label}').length > 2) return 'may contain {label} at most once';
  if (/\{label\}\{id\}|\{id\}\{label\}/.test(format)) return 'needs literal text between {label} and {id}';
  if (/\{[a-z]+\}/.test(format.replace(/\{(?:id|label)\}/g, ''))) return 'uses an unknown field';
  if (!format.split(/\{(?:id|label)\}/)[0]) return 'must start with literal text, e.g. {{';
  if (format.endsWith('{label}')) return 'must end with {id} or literal text';
  return undefined;
}

/** A key for stable ids: 64 hex characters. */
export function isIdKey(value: unknown): value is string {
  return typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
}

export function newIdKey(): string {
  return randomHex(ID_KEY_BYTES * 2);
}

function randomHex(length: number): string {
  let hex = '';
  while (hex.length < length) hex += crypto.randomUUID().replaceAll('-', '');
  return hex.slice(0, length);
}

/**
 * `stableKey` returns the local key for stable ids, or undefined (not loaded,
 * or ids are random): placeholders are then random.
 */
export function createScheme(
  format = DEFAULT_FORMAT,
  idLength = DEFAULT_ID_LENGTH,
  stableKey?: () => string | undefined,
): PlaceholderScheme {
  const usable = formatProblem(format) === undefined ? format : DEFAULT_FORMAT;
  const length = Math.min(MAX_ID_LENGTH, Math.max(MIN_ID_LENGTH, Math.round(idLength)));
  const parts = usable.split(/(\{(?:id|label)\})/);
  const source = parts
    .map(part =>
      part === '{id}'
        ? `[a-f0-9]{${length}}`
        : part === '{label}'
          ? '([A-Za-z][A-Za-z0-9_]{0,31})'
          : escapeRegExp(part),
    )
    .join('');
  const whole = new RegExp(`^${source}$`);
  const opening = parts[0] ?? '';
  const complete = new RegExp(`^${source}`);
  const maxLength = usable.length + 32 + length;

  return {
    format: usable,
    idLength: length,
    make(label, value) {
      const key = value === undefined ? undefined : stableKey?.();
      // The label is part of the input: one value under two labels gets two ids.
      const id = key ? hmacSha256Hex(key, `${label}\u0000${value}`).slice(0, length) : randomHex(length);
      return usable.replace('{label}', label).replace('{id}', id);
    },
    get stableIds() {
      return stableKey?.() !== undefined;
    },
    pattern: new RegExp(source, 'g'),
    labelOf(token) {
      const match = whole.exec(token);
      if (!match) return undefined;
      return usable.includes('{label}') ? match[1] : CUSTOM_LABEL;
    },
    holdPoint(text) {
      // Hold from the leftmost place near the end where a placeholder may have
      // started but is not complete yet: a partial opening, or an opening whose
      // placeholder could still grow (no whitespace, not yet a full match).
      let hold = text.length;
      const first = opening[0] ?? '';
      for (let start = text.lastIndexOf(first); start !== -1; start = text.lastIndexOf(first, start - 1)) {
        const tail = text.slice(start);
        if (tail.length > maxLength) break;
        const partial = opening.startsWith(tail);
        const growing = tail.startsWith(opening) && !/\s/.test(tail) && !complete.test(tail);
        if (partial || growing) hold = start;
        if (start === 0) break;
      }
      return hold;
    },
    example: label => usable.replace('{label}', label).replace('{id}', '<id>'),
  };
}

export const DEFAULT_SCHEME = createScheme();

/** One rule: a value, with an optional label or a fixed alias (structured fields, never parsed from text). */
export interface ValueRule {
  readonly value: string;
  readonly label?: string;
  readonly alias?: string;
  /** Match regardless of case; absent follows the `custom_case_insensitive` option. */
  readonly ignoreCase?: boolean;
  /** What the value is ("client company name"): told to the model, never the value. */
  readonly description?: string;
}

/**
 * Whether a description has the right shape: one line, printable, at most
 * `DESCRIPTION_LIMITS.maxLength` characters, no braces (it must not look like a
 * placeholder). Whether it holds its own value is checked by the rule's maker.
 */
export function isUsableDescription(description: string): boolean {
  return (
    description.length > 0 && description.length <= DESCRIPTION_LIMITS.maxLength && !/[\p{Cc}{}]/u.test(description)
  );
}

/**
 * An alias replaces the value verbatim, so it must not look like ordinary
 * text: restoring would turn every genuine occurrence back into the original.
 */
export function isUsableAlias(alias: string, value: string): boolean {
  return (
    alias.length >= 4 &&
    alias.length <= 64 &&
    !/\s/.test(alias) &&
    /[_\d]|[A-Z].*[A-Z]/.test(alias) &&
    alias !== value &&
    !alias.includes(value) &&
    !value.includes(alias)
  );
}

files.hooks/rules.ts:
/**
 * Rules kept in the plugin store (`$.store`): values the person adds, edits or
 * removes in the rules pane, accepts from a scan, or imports. Pure: callers
 * read and write the store. Never log, toast or return these values to the model.
 */
import {
  DESCRIPTION_HINT,
  EXPORT_FORMAT,
  EXPORT_VERSION,
  IGNORED_PREFIX,
  MIN_CUSTOM_VALUE_LENGTH,
  PATTERN_PREFIX,
  PREVIEW_DOTS,
  RULE_PREFIX,
} from './defaults.ts';
import { aliasOverlaps } from './matcher.ts';
import { patternKey, patternProblem, type PatternProblem, type PatternRule } from './patterns.ts';
import { CUSTOM_LABEL, isUsableAlias, isUsableDescription, LABEL_PATTERN, type ValueRule } from './placeholder.ts';

export { EXPORT_FORMAT, EXPORT_VERSION, IGNORED_PREFIX, PATTERN_PREFIX, RULE_PREFIX };

export const RULE_SOURCES = ['manual', 'scan', 'import'] as const;
export type RuleSource = (typeof RULE_SOURCES)[number];

export interface StoredRule {
  readonly value: string;
  readonly label?: string;
  readonly alias?: string;
  /** Match regardless of case; absent follows the `custom_case_insensitive` option. */
  readonly ignoreCase?: boolean;
  /** What the value is, told to the model instead of the value. */
  readonly description?: string;
  readonly source: RuleSource;
  /** ISO time the rule was first added; it orders the list. */
  readonly addedAt: string;
}

/** A pattern rule kept in the plugin store. Its example is checked on save and never stored. */
export interface StoredPattern extends Omit<PatternRule, 'example'> {
  readonly source: RuleSource;
  readonly addedAt: string;
}

export type RuleProblem =
  | 'empty'
  | 'too-short'
  | 'no-label'
  | 'invalid-label'
  | 'no-alias'
  | 'invalid-alias'
  | 'alias-in-use'
  | 'alias-overlap'
  | 'invalid-description'
  | 'description-has-value';

export type RuleParse = { readonly rule: StoredRule } | { readonly problem: RuleProblem };

/**
 * Rules are one per exact value: with case-sensitive matching (the default),
 * `Acme` and `ACME` are two values, each masked on its own.
 */
export function ruleKey(value: string): string {
  return value;
}

/** Checks a rule against the matcher's limits and the aliases already in use. */
export function makeRule(
  input: ValueRule,
  source: RuleSource,
  now: Date,
  existing: readonly ValueRule[] = [],
): RuleParse {
  const value = input.value.trim();
  if (value.length === 0) return { problem: 'empty' };
  if (value.length < MIN_CUSTOM_VALUE_LENGTH) return { problem: 'too-short' };
  const label = input.label?.trim().toUpperCase();
  const alias = input.alias?.trim();
  if (label !== undefined && !LABEL_PATTERN.test(label)) return { problem: 'invalid-label' };
  if (alias !== undefined && !isUsableAlias(alias, value)) return { problem: alias ? 'invalid-alias' : 'no-alias' };
  const description = input.description?.trim() || undefined;
  if (description !== undefined && !isUsableDescription(description)) return { problem: 'invalid-description' };
  // The description goes to the model: it must not hold the value it describes.
  if (description?.toLowerCase().includes(value.toLowerCase())) return { problem: 'description-has-value' };
  const others = existing.filter(rule => ruleKey(rule.value) !== ruleKey(value));
  if (alias && others.some(rule => rule.alias === alias)) return { problem: 'alias-in-use' };
  // An alias is restored wherever it appears: it must not overlap any other
  // value, and this value must not overlap another rule's alias.
  if (
    alias &&
    aliasOverlaps(
      alias,
      value,
      others.map(rule => rule.value),
    )
  )
    return { problem: 'alias-overlap' };
  const otherAliases = others.flatMap(rule => (rule.alias ? [rule.alias] : []));
  if (otherAliases.some(other => aliasOverlaps(other, '', [value]))) return { problem: 'alias-overlap' };
  return {
    rule: {
      value,
      ...(alias ? { alias } : label ? { label } : {}),
      ...(input.ignoreCase !== undefined ? { ignoreCase: input.ignoreCase } : {}),
      ...(description ? { description } : {}),
      source,
      addedAt: now.toISOString(),
    },
  };
}

export function describeProblem(problem: RuleProblem): string {
  switch (problem) {
    case 'empty':
      return 'Type a value first.';
    case 'too-short':
      return `Values need at least ${MIN_CUSTOM_VALUE_LENGTH} characters.`;
    case 'no-label':
      return 'Type a label, or pick one from the list.';
    case 'invalid-label':
      return 'A label is a letter, then letters, digits or _ (up to 32 characters).';
    case 'no-alias':
      return 'Type an alias, such as CLIENT_A.';
    case 'invalid-alias':
      return 'An alias needs 4 to 64 characters, no spaces, an underscore, a digit or two capitals, and must not contain the value.';
    case 'alias-in-use':
      return 'That alias already stands for another value.';
    case 'alias-overlap':
      return "That alias overlaps another rule's value, or this value overlaps another rule's alias.";
    case 'invalid-description':
      return DESCRIPTION_HINT;
    case 'description-has-value':
      return 'The description contains the value itself: describe what it is without writing it.';
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function valueRuleOf(item: Record<string, unknown>): ValueRule | undefined {
  if (typeof item.value !== 'string') return undefined;
  return {
    value: item.value,
    ...(typeof item.label === 'string' ? { label: item.label } : {}),
    ...(typeof item.alias === 'string' ? { alias: item.alias } : {}),
    ...(typeof item.ignoreCase === 'boolean' ? { ignoreCase: item.ignoreCase } : {}),
    ...(typeof item.description === 'string' ? { description: item.description } : {}),
  };
}

function patternRuleOf(item: Record<string, unknown>): PatternRule | undefined {
  if (typeof item.pattern !== 'string') return undefined;
  return {
    pattern: item.pattern,
    ...(typeof item.label === 'string' ? { label: item.label.toUpperCase() } : {}),
    ignoreCase: item.ignoreCase === true,
    wholeWord: item.wholeWord !== false,
    group: typeof item.group === 'number' && Number.isInteger(item.group) ? item.group : 0,
    ...(typeof item.description === 'string' ? { description: item.description } : {}),
  };
}

// Checking a pattern runs probes; remember results so loading the store on every prompt stays cheap.
const checked = new Map<string, PatternProblem | 'ok'>();
function checkOnce(rule: PatternRule): PatternProblem | undefined {
  const key = `${patternKey(rule)}\u0002${rule.label ?? ''}\u0002${rule.description ?? ''}`;
  let result = checked.get(key);
  if (result === undefined) {
    result = patternProblem({ ...rule, example: undefined }) ?? 'ok';
    if (checked.size > 1000) checked.clear();
    checked.set(key, result);
  }
  return result === 'ok' ? undefined : result;
}

/** A pattern rule from the form or an import, checked; the example (if any) must match. */
export function makePattern(
  input: PatternRule,
  source: RuleSource,
  now: Date,
): { pattern: StoredPattern } | { problem: PatternProblem } {
  const { description: rawDescription, ...rest } = input;
  const description = rawDescription?.trim() || undefined;
  const rule: PatternRule = {
    ...rest,
    pattern: input.pattern.trim(),
    ...(input.label ? { label: input.label.trim().toUpperCase() } : {}),
    ...(description ? { description } : {}),
  };
  const problem = input.example !== undefined ? patternProblem(rule) : checkOnce(rule);
  if (problem) return { problem };
  const { example: _example, ...kept } = rule;
  return {
    pattern: {
      ...kept,
      ...(kept.label === CUSTOM_LABEL ? { label: undefined } : {}),
      source,
      addedAt: now.toISOString(),
    },
  };
}

/** Reads stored pattern rules, dropping any that are malformed or fail the checks. */
export function parseStoredPatterns(raw: unknown): StoredPattern[] {
  if (!Array.isArray(raw)) return [];
  const patterns: StoredPattern[] = [];
  for (const item of raw) {
    if (!isRecord(item)) continue;
    const rule = patternRuleOf(item);
    if (!rule || checkOnce(rule)) continue;
    if (patterns.some(one => patternKey(one) === patternKey(rule))) continue;
    patterns.push({
      ...rule,
      source: RULE_SOURCES.find(one => one === item.source) ?? 'manual',
      addedAt: typeof item.addedAt === 'string' ? item.addedAt : new Date(0).toISOString(),
    });
  }
  return patterns.sort((a, b) => a.addedAt.localeCompare(b.addedAt) || a.pattern.localeCompare(b.pattern));
}

/** Adds a pattern, or updates the label of the one with the same source and flags (keeping its place). */
export function upsertPattern(
  list: readonly StoredPattern[],
  pattern: StoredPattern,
): { patterns: StoredPattern[]; change: 'added' | 'updated' | 'unchanged' } {
  const index = list.findIndex(one => patternKey(one) === patternKey(pattern));
  if (index === -1) return { patterns: [...list, pattern], change: 'added' };
  const current = list[index] as StoredPattern;
  if (
    (current.label ?? CUSTOM_LABEL) === (pattern.label ?? CUSTOM_LABEL) &&
    current.description === pattern.description
  )
    return { patterns: [...list], change: 'unchanged' };
  const updated = { ...pattern, addedAt: current.addedAt };
  return { patterns: list.map((one, i) => (i === index ? updated : one)), change: 'updated' };
}

/** Identity of a pattern list, for change detection and caches. */
export function patternsKey(list: readonly StoredPattern[]): string {
  return JSON.stringify(list.map(one => [patternKey(one), one.label ?? '', one.description ?? '']));
}

/** Reads the stored list, dropping anything malformed (the store is a local file a person may edit). */
export function parseStoredRules(raw: unknown): StoredRule[] {
  if (!Array.isArray(raw)) return [];
  const rules: StoredRule[] = [];
  for (const item of raw) {
    const input = isRecord(item) ? valueRuleOf(item) : undefined;
    if (!input || !isRecord(item)) continue;
    const source = RULE_SOURCES.find(one => one === item.source) ?? 'manual';
    const parsed = makeRule(input, source, new Date(0), rules);
    if (!('rule' in parsed) || rules.some(rule => ruleKey(rule.value) === ruleKey(parsed.rule.value))) continue;
    rules.push({ ...parsed.rule, addedAt: typeof item.addedAt === 'string' ? item.addedAt : parsed.rule.addedAt });
  }
  return rules;
}

/** Adds a rule, or replaces the one for the same value (a new label or alias). */
export function upsertRule(
  rules: readonly StoredRule[],
  rule: StoredRule,
): { rules: StoredRule[]; change: 'added' | 'updated' | 'unchanged' } {
  const key = ruleKey(rule.value);
  const index = rules.findIndex(one => ruleKey(one.value) === key);
  if (index === -1) return { rules: [...rules, rule], change: 'added' };
  const current = rules[index] as StoredRule;
  if (
    current.value === rule.value &&
    current.label === rule.label &&
    current.alias === rule.alias &&
    current.ignoreCase === rule.ignoreCase &&
    current.description === rule.description
  )
    return { rules: [...rules], change: 'unchanged' };
  // An update keeps the rule's place: its added time stays.
  const updated = { ...rule, addedAt: current.addedAt };
  return { rules: rules.map((one, i) => (i === index ? updated : one)), change: 'updated' };
}

export function removeRule(rules: readonly StoredRule[], value: string): StoredRule[] {
  const key = ruleKey(value);
  return rules.filter(rule => ruleKey(rule.value) !== key);
}

/**
 * Rules for matching: the plugin options (keychain) first, so an option's
 * label or alias wins over a stored rule for the same value.
 */
export function mergedRules(optionRules: readonly ValueRule[], stored: readonly StoredRule[]): ValueRule[] {
  return [...optionRules, ...stored];
}

/** A short form for the pane: the first character, dots and the length. */
export function maskPreview(value: string): string {
  const first = Array.from(value)[0] ?? '';
  return `${first}${'•'.repeat(PREVIEW_DOTS)} (${Array.from(value).length})`;
}

/** The export file: originals in plain text, so the caller warns where it is written. */
export function exportRules(rules: readonly StoredRule[], now: Date, patterns: readonly StoredPattern[] = []): string {
  return `${JSON.stringify(
    {
      format: EXPORT_FORMAT,
      version: EXPORT_VERSION,
      exportedAt: now.toISOString(),
      rules: rules.map(rule => ({
        value: rule.value,
        ...(rule.label ? { label: rule.label } : {}),
        ...(rule.alias ? { alias: rule.alias } : {}),
        ...(rule.ignoreCase !== undefined ? { ignoreCase: rule.ignoreCase } : {}),
        ...(rule.description ? { description: rule.description } : {}),
      })),
      patterns: patterns.map(one => ({
        pattern: one.pattern,
        ...(one.label ? { label: one.label } : {}),
        ignoreCase: one.ignoreCase,
        wholeWord: one.wholeWord,
        group: one.group,
        ...(one.description ? { description: one.description } : {}),
      })),
    },
    null,
    2,
  )}\n`;
}

/** An import file is an export: JSON whose rules have `value`, and optionally `label` or `alias`. */
/** `patterns` is absent when the file has no patterns list (an older export): saved patterns then stay. */
export function parseImport(text: string): { items: ValueRule[]; patterns?: PatternRule[] } | { error: string } {
  let data: unknown;
  try {
    data = JSON.parse(text);
  } catch {
    return { error: `The file is not a ${EXPORT_FORMAT} export (JSON).` };
  }
  if (!isRecord(data) || data.format !== EXPORT_FORMAT || !Array.isArray(data.rules)) {
    return { error: `The file is not a ${EXPORT_FORMAT} export.` };
  }
  if (typeof data.version !== 'number' || data.version > EXPORT_VERSION) {
    return { error: 'The file comes from a newer Redact Restore version.' };
  }
  // An entry without a string value is kept as an empty value, so it counts as invalid.
  const items = data.rules.map(item => (isRecord(item) ? (valueRuleOf(item) ?? { value: '' }) : { value: '' }));
  if (!Array.isArray(data.patterns)) return { items };
  return {
    items,
    // A pattern entry without a string pattern is kept empty, so it counts as invalid.
    patterns: data.patterns.map(item => (isRecord(item) ? (patternRuleOf(item) ?? EMPTY_PATTERN) : EMPTY_PATTERN)),
  };
}

const EMPTY_PATTERN: PatternRule = { pattern: '', ignoreCase: false, wholeWord: true, group: 0 };

/** Merges imported pattern rules into the stored ones, or replaces them all. */
export function applyPatternImport(
  existing: readonly StoredPattern[],
  items: readonly PatternRule[],
  mode: 'merge' | 'replace',
  now: Date,
): { patterns: StoredPattern[]; added: number; updated: number; unchanged: number; invalid: number } {
  let patterns: StoredPattern[] = mode === 'replace' ? [] : [...existing];
  let added = 0;
  let updated = 0;
  let unchanged = 0;
  let invalid = 0;
  for (const item of items) {
    const made = makePattern(item, 'import', now);
    if (!('pattern' in made)) {
      invalid += 1;
      continue;
    }
    const result = upsertPattern(patterns, made.pattern);
    patterns = result.patterns;
    if (result.change === 'added') added += 1;
    else if (result.change === 'updated') updated += 1;
    else unchanged += 1;
  }
  return { patterns, added, updated, unchanged, invalid };
}

export interface ImportSummary {
  readonly rules: StoredRule[];
  readonly added: number;
  readonly updated: number;
  readonly unchanged: number;
  readonly invalid: number;
}

/** Merges imported entries into the stored rules, or replaces them all. */
export function applyImport(
  existing: readonly StoredRule[],
  items: readonly ValueRule[],
  mode: 'merge' | 'replace',
  now: Date,
  /** Rules kept elsewhere (the plugin options) that aliases must not clash with. */
  others: readonly ValueRule[] = [],
): ImportSummary {
  let rules: StoredRule[] = mode === 'replace' ? [] : [...existing];
  let added = 0;
  let updated = 0;
  let unchanged = 0;
  let invalid = 0;
  for (const item of items) {
    const parsed = makeRule(item, 'import', now, [...others, ...rules]);
    if (!('rule' in parsed)) {
      invalid += 1;
      continue;
    }
    const result = upsertRule(rules, parsed.rule);
    rules = result.rules;
    if (result.change === 'added') added += 1;
    else if (result.change === 'updated') updated += 1;
    else unchanged += 1;
  }
  return { rules, added, updated, unchanged, invalid };
}

/** SHA-256 hex of a value: how dismissed scan candidates are remembered without keeping them. */
export async function fingerprint(value: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(ruleKey(value)));
  return Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
}

/** The store key of a rule or a dismissed candidate: a prefix and the value's fingerprint. */
export async function storeKeyFor(prefix: string, value: string): Promise<string> {
  return `${prefix}${await fingerprint(value)}`;
}

export function isPatternKey(key: string): boolean {
  return key.startsWith(PATTERN_PREFIX) && /^[a-f0-9]{64}$/.test(key.slice(PATTERN_PREFIX.length));
}

export function isRuleKey(key: string): boolean {
  return key.startsWith(RULE_PREFIX) && /^[a-f0-9]{64}$/.test(key.slice(RULE_PREFIX.length));
}

/** Oldest first, then by value, so every session lists the rules in one order. */
export function sortRules(rules: readonly StoredRule[]): StoredRule[] {
  return [...rules].sort((a, b) => a.addedAt.localeCompare(b.addedAt) || a.value.localeCompare(b.value));
}

/** Identity of a rule list, for change detection and caches. */
export function rulesKey(rules: readonly StoredRule[]): string {
  return JSON.stringify(
    rules.map(rule => [
      rule.value,
      rule.label ?? '',
      rule.alias ?? '',
      rule.ignoreCase ?? '',
      rule.description ?? '',
      rule.source,
    ]),
  );
}

/** `~/…` for a path under home, so command output never spells the home folder (any case or separator). */
export function displayPath(path: string, home: string | undefined): string {
  if (!home) return path;
  const fold = (text: string) => text.replace(/\\/g, '/').toLowerCase();
  const base = fold(home).replace(/\/+$/, '');
  const target = fold(path);
  return target === base || target.startsWith(`${base}/`) ? `~${path.slice(home.replace(/[\\/]+$/, '').length)}` : path;
}

/** Expands a leading `~` against home; leaves every other path as typed. */
export function expandHome(path: string, home: string | undefined): string {
  if (!home || !(path === '~' || path.startsWith('~/') || path.startsWith('~\\'))) return path;
  return `${home.replace(/[\\/]+$/, '')}${path.slice(1)}`;
}

files.hooks/patterns.ts:
/**
 * Pattern rules: a user's own regular expression, as structured fields (never
 * parsed from an entry string). Pure.
 *
 * JavaScript cannot time out a regex, and timing probes are neither reliable nor
 * able to catch quadratic slowdowns, so a pattern must fall inside a safe subset,
 * checked deterministically:
 * - quantifiers only on single atoms (a character, an escape, a class), never on
 *   a group, which rules out exponential backtracking;
 * - at most two free repeats (`*`, `+`, `{n,}`);
 * - no backreferences and no lookarounds;
 * - a fixed text of 3+ characters every match contains (the keyword).
 * At run time the regex runs only in a window around each keyword occurrence
 * (as gitleaks does), so even a quadratic pattern costs a bounded amount per hit.
 */
import {
  CUSTOM_LABEL,
  KEYWORD_RESCAN_LIMIT,
  KEYWORD_WINDOW_AFTER,
  KEYWORD_WINDOW_BEFORE,
  MIN_CUSTOM_VALUE_LENGTH,
  PATTERN_LIMITS,
  DESCRIPTION_HINT,
} from './defaults.ts';
import type { Detector, Span } from './detectors.ts';
import { LABEL_PATTERN, isUsableDescription } from './placeholder.ts';

export interface PatternRule {
  /** The regex source, without slashes or flags. */
  readonly pattern: string;
  readonly label?: string;
  readonly ignoreCase: boolean;
  /** Only where no letter or digit touches either end (GitHub's default boundary). */
  readonly wholeWord: boolean;
  /** 0 masks the whole match; N masks capture group N only. */
  readonly group: number;
  /** A sample that must match when the rule is saved; never sent anywhere. */
  readonly example?: string;
  /** What a match is ("internal API token"): told to the model; must not match the pattern. */
  readonly description?: string;
}

export type PatternProblem =
  | 'empty'
  | 'too-long'
  | 'invalid'
  | 'unbalanced'
  | 'backreference'
  | 'lookaround'
  | 'group-quantifier'
  | 'too-many-repeats'
  | 'no-keyword'
  | 'no-group'
  | 'invalid-label'
  | 'no-example'
  | 'example-no-match'
  | 'example-too-short'
  | 'invalid-description'
  | 'description-has-value';

/** What the scanner learns about a source: a problem, or its keyword and capture groups. */
interface Shape {
  readonly problem?: PatternProblem;
  readonly keyword?: string;
  readonly groups: number;
}

const QUANTIFIER = /^(?:[*+?]|\{\d+(?:,\d*)?\})/;
const LITERAL_CHAR = /[A-Za-z0-9_\-:#@/%=~!<>"' ]/;
const LOOKAROUNDS = ['(?=', '(?!', '(?<=', '(?<!'];

/**
 * Walks the source once. Escapes and character classes are single atoms; a
 * quantifier may follow only an atom; the longest run of plain characters at the
 * top level (outside any alternation, not made optional or repeated) is the keyword.
 */
function analyze(source: string): Shape {
  let depth = 0;
  let groups = 0;
  let freeRepeats = 0;
  let topAlternation = false;
  let run = '';
  let best = '';
  const endRun = () => {
    if (run.trim().length > best.trim().length) best = run;
    run = '';
  };
  let i = 0;
  while (i < source.length) {
    const ch = source.charAt(i);
    if (ch === '(') {
      endRun();
      if (LOOKAROUNDS.some(open => source.startsWith(open, i))) return { problem: 'lookaround', groups };
      depth += 1;
      if (source.startsWith('(?:', i)) {
        i += 3;
      } else if (source.startsWith('(?<', i)) {
        groups += 1;
        const close = source.indexOf('>', i);
        i = close > 0 ? close + 1 : i + 3;
      } else {
        groups += 1;
        i += 1;
      }
      continue;
    }
    if (ch === ')') {
      endRun();
      if (depth === 0) return { problem: 'unbalanced', groups };
      depth -= 1;
      i += 1;
      if (QUANTIFIER.test(source.slice(i))) return { problem: 'group-quantifier', groups };
      continue;
    }
    if (ch === '|') {
      endRun();
      if (depth === 0) topAlternation = true;
      i += 1;
      continue;
    }
    let atom: string;
    let literal: string | undefined;
    if (ch === '\\') {
      const next = source.charAt(i + 1);
      if (/[1-9]/.test(next) || next === 'k') return { problem: 'backreference', groups };
      atom = source.slice(i, i + 2);
      // An escaped punctuation character is a literal; \d, \w, \s, \b … are not.
      if (/[^A-Za-z0-9]/.test(next)) literal = next;
    } else if (ch === '[') {
      let end = i + 1;
      while (end < source.length && source.charAt(end) !== ']') end += source.charAt(end) === '\\' ? 2 : 1;
      atom = source.slice(i, end + 1);
    } else {
      atom = ch;
      if (LITERAL_CHAR.test(ch)) literal = ch;
    }
    i += atom.length;
    const quantifier = QUANTIFIER.exec(source.slice(i))?.[0];
    if (quantifier) {
      i += quantifier.length;
      if (source.charAt(i) === '?') i += 1;
      if (quantifier === '*' || quantifier === '+' || quantifier.endsWith(',}')) freeRepeats += 1;
      if (freeRepeats > PATTERN_LIMITS.maxFreeRepeats) return { problem: 'too-many-repeats', groups };
      endRun();
      continue;
    }
    if (literal !== undefined && depth === 0) run += literal;
    else endRun();
  }
  endRun();
  if (depth !== 0) return { problem: 'unbalanced', groups };
  const keyword = topAlternation ? '' : best.trim();
  return keyword.length >= PATTERN_LIMITS.minKeyword ? { keyword, groups } : { problem: 'no-keyword', groups };
}

/** The rule as a global regex with match indices: whole-word guards added, the user's own flags never accepted. */
export function compilePattern(rule: PatternRule): RegExp {
  const source = rule.wholeWord ? `(?<![A-Za-z0-9])(?:${rule.pattern})(?![A-Za-z0-9])` : rule.pattern;
  return new RegExp(source, rule.ignoreCase ? 'dgiu' : 'dgu');
}

/** The span a match masks: the whole match, or its capture group, at the group's own position. */
function maskedSpan(match: RegExpExecArray, group: number, offset: number): { start: number; end: number } | undefined {
  const range = match.indices?.[group];
  if (!range) return undefined;
  return { start: offset + range[0], end: offset + range[1] };
}

/** Windows around each keyword occurrence, merged; the regex runs only there. */
function keywordWindows(text: string, keyword: string, ignoreCase: boolean): Span[] {
  const haystack = ignoreCase ? text.toLowerCase() : text;
  const needle = ignoreCase ? keyword.toLowerCase() : keyword;
  const windows: Array<{ start: number; end: number }> = [];
  for (let at = haystack.indexOf(needle); at !== -1; at = haystack.indexOf(needle, at + needle.length)) {
    const window = {
      start: Math.max(0, at - KEYWORD_WINDOW_BEFORE),
      end: Math.min(text.length, at + needle.length + KEYWORD_WINDOW_AFTER),
    };
    const last = windows[windows.length - 1];
    if (last && window.start <= last.end) last.end = Math.max(last.end, window.end);
    else windows.push(window);
  }
  return windows;
}

/** Every span the rule masks in a text: matches found in keyword windows, a match at a window's edge rescanned. */
function findSpans(rule: PatternRule, regex: RegExp, keyword: string, text: string): Span[] {
  const spans: Span[] = [];
  let sticky: RegExp | undefined;
  for (const window of keywordWindows(text, keyword, rule.ignoreCase)) {
    const slice = text.slice(window.start, window.end);
    regex.lastIndex = 0;
    for (let match = regex.exec(slice); match; match = regex.exec(slice)) {
      let found: RegExpExecArray = match;
      let offset = window.start;
      if (match.index + match[0].length >= slice.length && window.end < text.length) {
        sticky ??= new RegExp(regex.source, regex.flags.replace('g', 'y'));
        sticky.lastIndex = window.start + match.index;
        const longer = sticky.exec(text.slice(0, Math.min(text.length, sticky.lastIndex + KEYWORD_RESCAN_LIMIT)));
        if (longer) {
          found = longer;
          offset = 0;
        }
      }
      const span = maskedSpan(found, rule.group, offset);
      // A match that starts at the window's left edge may have begun earlier:
      // widen the mask over the run of non-space characters it sits in (fail safe).
      if (span && offset === window.start && span.start === window.start && window.start > 0) {
        let start = span.start;
        const limit = Math.max(0, span.start - KEYWORD_RESCAN_LIMIT);
        while (start > limit && !/\s/.test(text.charAt(start - 1))) start -= 1;
        span.start = start;
      }
      if (span && span.end - span.start >= MIN_CUSTOM_VALUE_LENGTH) spans.push(span);
      if (match[0].length === 0) regex.lastIndex += 1;
    }
  }
  return spans;
}

/** What is wrong with a rule, or undefined when it may be saved. Deterministic: no timing. */
export function patternProblem(rule: PatternRule): PatternProblem | undefined {
  const source = rule.pattern;
  if (!source.trim()) return 'empty';
  if (source.length > PATTERN_LIMITS.maxLength) return 'too-long';
  if (rule.label !== undefined && !LABEL_PATTERN.test(rule.label)) return 'invalid-label';
  try {
    // On its own first: a stray `)` must not hide behind the whole-word wrapper.
    new RegExp(source, 'u');
    compilePattern(rule);
  } catch {
    return 'invalid';
  }
  const shape = analyze(source);
  if (shape.problem) return shape.problem;
  if (rule.group < 0 || rule.group > shape.groups) return 'no-group';
  if (rule.description !== undefined) {
    if (!isUsableDescription(rule.description)) return 'invalid-description';
    // The description goes to the model: it must not itself hold a value the rule masks.
    if (findSpans(rule, compilePattern(rule), shape.keyword ?? '', rule.description).length > 0)
      return 'description-has-value';
  }
  if (rule.example === undefined) return undefined;
  if (!rule.example.trim()) return 'no-example';
  if (findSpans(rule, compilePattern(rule), shape.keyword ?? '', rule.example).length > 0) return undefined;
  return compilePattern(rule).exec(rule.example) ? 'example-too-short' : 'example-no-match';
}

/** The keyword a valid pattern is found by, for the form to show. */
export function patternKeyword(pattern: string): string | undefined {
  return analyze(pattern).keyword;
}

export function describePatternProblem(problem: PatternProblem): string {
  switch (problem) {
    case 'empty':
      return 'Type a pattern first.';
    case 'too-long':
      return `A pattern can be at most ${PATTERN_LIMITS.maxLength} characters.`;
    case 'invalid':
      return 'That is not a valid regular expression (patterns use the u flag: escape only characters that need it, so write - rather than \\-).';
    case 'unbalanced':
      return 'The parentheses do not balance.';
    case 'backreference':
      return 'Backreferences (\\1, \\k<name>) are not allowed.';
    case 'lookaround':
      return 'Lookarounds such as (?=…) and (?<!…) are not allowed; use Whole word for boundaries.';
    case 'group-quantifier':
      return 'Repeat single characters or classes, not groups: write [a-z0-9.-]+ rather than ([a-z0-9-]+\\.)+.';
    case 'too-many-repeats':
      return `Use at most ${PATTERN_LIMITS.maxFreeRepeats} open-ended repeats (*, +, {n,}); give the others a size such as {1,40}.`;
    case 'no-keyword':
      return `The pattern needs a fixed text of at least ${PATTERN_LIMITS.minKeyword} characters that every match contains, such as ACME- (not inside a group or a | alternative).`;
    case 'no-group':
      return 'The pattern has no capture group with that number.';
    case 'invalid-label':
      return 'A label is a letter, then letters, digits or _ (up to 32 characters).';
    case 'no-example':
      return 'Type an example that the pattern should match.';
    case 'example-no-match':
      return 'The pattern does not match the example.';
    case 'example-too-short':
      return `The part the pattern masks in the example must be at least ${MIN_CUSTOM_VALUE_LENGTH} characters.`;
    case 'invalid-description':
      return DESCRIPTION_HINT;
    case 'description-has-value':
      return 'The description matches the pattern itself: describe what the value is without writing one.';
  }
}

/** A detector for the matching code: spans of each match (or its group), under the rule's label. */
export function patternDetector(rule: PatternRule, id: string): Detector {
  const regex = compilePattern(rule);
  const keyword = analyze(rule.pattern).keyword ?? '';
  const label = rule.label ?? CUSTOM_LABEL;
  return {
    id,
    label,
    groups: [],
    defaultOn: true,
    // Same standing as exact values: a user's own rule beats the built-in detectors.
    rank: 0,
    ...(rule.description ? { description: rule.description } : {}),
    find: text => (keyword ? findSpans(rule, regex, keyword, text) : []),
  };
}

/** A stable identity for a rule: its source and the flags that change what it matches. */
export function patternKey(rule: Pick<PatternRule, 'pattern' | 'ignoreCase' | 'wholeWord' | 'group'>): string {
  return `${rule.pattern}\u0001${rule.ignoreCase ? 'i' : ''}${rule.wholeWord ? 'w' : ''}${rule.group}`;
}

files.hooks/scan.ts:
/**
 * Finds likely private values on this machine and in this folder: the git
 * identity, remotes and recent authors, the host and user names, `.env` values
 * and the package author. Pure: the caller gathers the inputs (git, files) and
 * shows candidates only in the local pane. Never send a candidate's value to the model.
 */
import {
  BOT_AUTHOR,
  ENV_EXAMPLE,
  ENV_FILE,
  GENERIC_ACCOUNTS,
  LOCAL_HOST_SUFFIX,
  MIN_CUSTOM_VALUE_LENGTH,
  PUBLIC_GIT_HOSTS,
  SECRET_KEY,
  TRIVIAL_VALUE,
  SCAN_DESCRIPTIONS,
} from './defaults.ts';
import { envAssignments, findInternalHosts } from './detectors.ts';
import { findPrivateMatches, type MatchingOptions } from './matcher.ts';
import { fingerprint, ruleKey } from './rules.ts';

export interface ScanCandidate {
  readonly value: string;
  /** The label a rule for it gets: NAME, EMAIL, ORG, HOST, PROJECT, USER, SECRET or ENV. */
  readonly label: string;
  /** Where it was found, without the value (`git config user.name`, `.env (DB_PASSWORD)`). */
  readonly source: string;
  /** What it is, for the rule's description (told to the model, never the value). */
  readonly description?: string;
}

export interface ScanInputs {
  readonly gitName?: string;
  readonly gitEmail?: string;
  /** `git remote -v` output. */
  readonly remotes?: string;
  /** `git log --format=%an%x00%ae` output. */
  readonly logAuthors?: string;
  readonly hostname?: string;
  /** The home folder path; its last segment is the account name. */
  readonly home?: string;
  readonly envFiles?: ReadonlyArray<{ readonly name: string; readonly text: string }>;
  /** package.json text. */
  readonly packageJson?: string;
}

export { PUBLIC_GIT_HOSTS };

/** Whether a root-level file name is a real `.env` file (not an example). */
export function isEnvFile(name: string): boolean {
  return ENV_FILE.test(name) && !ENV_EXAMPLE.test(name);
}

/** `KEY=value` pairs of a dotenv file: `export`, quotes and trailing comments handled. */
export function parseEnvFile(text: string): Array<{ key: string; value: string }> {
  const pairs: Array<{ key: string; value: string }> = [];
  for (const line of text.split(/\r?\n/)) {
    const match = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_.-]*)\s*=\s*(.*)$/.exec(line);
    if (!match) continue;
    const key = match[1] ?? '';
    let value = (match[2] ?? '').trim();
    const quote = value.charAt(0);
    if ((quote === '"' || quote === "'" || quote === '`') && value.indexOf(quote, 1) > 0) {
      value = value.slice(1, value.indexOf(quote, 1));
    } else {
      value = value.replace(/\s+#.*$/, '').trim();
    }
    pairs.push({ key, value });
  }
  return pairs;
}

/**
 * Host, owner and repository of each remote URL (https, ssh, scp-like):
 * the owner is the first path segment, the repository the last, so GitLab
 * subgroups and Azure DevOps (`v3/org/project/repo`, `org/project/_git/repo`) parse.
 */
export function parseRemotes(text: string): Array<{ host: string; owner: string; repo: string }> {
  const found: Array<{ host: string; owner: string; repo: string }> = [];
  for (const line of text.split(/\r?\n/)) {
    const url = line.split(/\s+/)[1];
    if (!url) continue;
    const match = /^(?:[a-z+]+:\/\/)?(?:[^@/\s]+@)?([^/:\s]+)(?::\d+)?[:/](.+?)(?:\.git)?\/?$/i.exec(url);
    if (!match) continue;
    const segments = (match[2] ?? '')
      .split('/')
      .filter(segment => segment && segment !== '_git' && !/^v\d+$/.test(segment));
    if (segments.length < 2) continue;
    found.push({
      host: (match[1] ?? '').toLowerCase(),
      owner: segments[0] ?? '',
      repo: segments[segments.length - 1] ?? '',
    });
  }
  return found;
}

/** `Name <email> (url)` or `{ name, email }` from package.json's `author`. */
export function packageAuthor(text: string): { name?: string; email?: string } {
  let data: unknown;
  try {
    data = JSON.parse(text);
  } catch {
    return {};
  }
  if (typeof data !== 'object' || data === null || !('author' in data)) return {};
  const author = data.author;
  if (typeof author === 'string') {
    const match = /^([^<(]*?)\s*(?:<([^>]+)>)?\s*(?:\([^)]*\))?$/.exec(author.trim());
    return {
      ...(match?.[1] ? { name: match[1] } : {}),
      ...(match?.[2] ? { email: match[2] } : {}),
    };
  }
  if (typeof author === 'object' && author !== null) {
    const name = 'name' in author && typeof author.name === 'string' ? author.name : undefined;
    const email = 'email' in author && typeof author.email === 'string' ? author.email : undefined;
    return { ...(name ? { name } : {}), ...(email ? { email } : {}) };
  }
  return {};
}

function lastSegment(path: string): string {
  return (
    path
      .replace(/[\\/]+$/, '')
      .split(/[\\/]/)
      .pop() ?? ''
  );
}

/** Every candidate, first source wins for a repeated value; nothing shorter than a rule allows. */
export function collectCandidates(inputs: ScanInputs): ScanCandidate[] {
  const candidates: ScanCandidate[] = [];
  const seen = new Set<string>();
  const add = (value: string | undefined, label: string, source: string, description?: string) => {
    const trimmed = value?.trim() ?? '';
    if (trimmed.length < MIN_CUSTOM_VALUE_LENGTH || TRIVIAL_VALUE.test(trimmed)) return;
    const key = ruleKey(trimmed);
    if (seen.has(key)) return;
    seen.add(key);
    candidates.push({ value: trimmed, label, source, ...(description ? { description } : {}) });
  };

  add(inputs.gitName, 'NAME', 'git config user.name', SCAN_DESCRIPTIONS.gitName);
  add(inputs.gitEmail, 'EMAIL', 'git config user.email', SCAN_DESCRIPTIONS.gitEmail);

  for (const remote of parseRemotes(inputs.remotes ?? '')) {
    const isPublic = PUBLIC_GIT_HOSTS.includes(remote.host);
    if (!isPublic) add(remote.host, 'HOST', 'git remote host', SCAN_DESCRIPTIONS.remoteHost);
    add(remote.owner, 'ORG', 'git remote owner', SCAN_DESCRIPTIONS.remoteOwner);
    if (!isPublic) add(remote.repo, 'PROJECT', 'git remote repository', SCAN_DESCRIPTIONS.remoteRepo);
  }

  for (const line of (inputs.logAuthors ?? '').split(/\r?\n/)) {
    const [name, email] = line.split('\u0000');
    if (!name || BOT_AUTHOR.test(name) || BOT_AUTHOR.test(email ?? '')) continue;
    add(name, 'NAME', 'git log author', SCAN_DESCRIPTIONS.logName);
    add(email, 'EMAIL', 'git log author', SCAN_DESCRIPTIONS.logEmail);
  }

  const author = inputs.packageJson ? packageAuthor(inputs.packageJson) : {};
  add(author.name, 'NAME', 'package.json author', SCAN_DESCRIPTIONS.packageName);
  add(author.email, 'EMAIL', 'package.json author', SCAN_DESCRIPTIONS.packageEmail);

  const host = inputs.hostname?.trim().replace(LOCAL_HOST_SUFFIX, '');
  add(host, 'HOST', 'computer name', SCAN_DESCRIPTIONS.computer);
  const account = inputs.home ? lastSegment(inputs.home) : '';
  if (!GENERIC_ACCOUNTS.includes(account.toLowerCase()))
    add(account, 'USER', 'home folder name', SCAN_DESCRIPTIONS.account);

  for (const file of inputs.envFiles ?? []) {
    for (const { key, value } of parseEnvFile(file.text)) {
      if (value.startsWith('${') || value.includes('{{')) continue;
      add(value, SECRET_KEY.test(key) ? 'SECRET' : 'ENV', `${file.name} (${key})`, SCAN_DESCRIPTIONS.envValue(key));
    }
  }
  return candidates;
}

/**
 * Candidates in any text files (a path scan): `KEY=value` values and host names
 * on private networks. Values masked anyway are counted, not offered, by `triage`.
 */
export function fileCandidates(
  files: ReadonlyArray<{ readonly name: string; readonly text: string }>,
): ScanCandidate[] {
  const candidates: ScanCandidate[] = [];
  const seen = new Set<string>();
  const add = (value: string, label: string, source: string, description?: string) => {
    const key = ruleKey(value);
    if (value.length < MIN_CUSTOM_VALUE_LENGTH || seen.has(key)) return;
    seen.add(key);
    candidates.push({ value, label, source, ...(description ? { description } : {}) });
  };
  for (const file of files) {
    for (const { key, value } of envAssignments(file.text)) {
      add(value, SECRET_KEY.test(key) ? 'SECRET' : 'ENV', `${file.name} (${key})`, SCAN_DESCRIPTIONS.envValue(key));
    }
    for (const { start, end } of findInternalHosts(file.text)) add(file.text.slice(start, end), 'HOST', file.name);
  }
  return candidates;
}

/** The KEY=value values in these files: masked wherever they appear as an assignment while the env detector is on. */
export function assignedValues(files: ReadonlyArray<{ readonly text: string }>): Set<string> {
  return new Set(files.flatMap(file => envAssignments(file.text).map(({ value }) => value)));
}

/** Distinct values the current rules and detectors already mask in these files, by label. */
export function maskedKinds(
  files: ReadonlyArray<{ readonly text: string }>,
  matching: MatchingOptions,
): Array<readonly [string, number]> {
  const byLabel = new Map<string, Set<string>>();
  for (const file of files) {
    for (const match of findPrivateMatches(file.text, matching)) {
      const values = byLabel.get(match.category) ?? new Set<string>();
      values.add(match.value);
      byLabel.set(match.category, values);
    }
  }
  return [...byLabel.entries()]
    .map(([label, values]) => [label, values.size] as const)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}

/** Candidates by label, for command output that must not carry values: `2 NAME, 1 HOST`. */
export function countByLabel(candidates: readonly ScanCandidate[]): string {
  const counts = new Map<string, number>();
  for (const candidate of candidates) counts.set(candidate.label, (counts.get(candidate.label) ?? 0) + 1);
  return [...counts.entries()].map(([label, count]) => `${count} ${label}`).join(', ');
}

/** Whether the current rules, the email scanner or a detector already mask the whole value. */
export function isMasked(value: string, matching: MatchingOptions): boolean {
  return findPrivateMatches(value, matching).some(match => match.start === 0 && match.end === value.length);
}

/** Splits found values into new ones, ones already masked, and ones dismissed before. */
export async function triage(
  found: readonly ScanCandidate[],
  matching: MatchingOptions,
  ignored: ReadonlySet<string>,
  /** Also masked in context (a KEY=value value the env detector hides), though not on its own. */
  maskedInContext: (candidate: ScanCandidate) => boolean = () => false,
): Promise<{ candidates: ScanCandidate[]; covered: number; ignored: number }> {
  const candidates: ScanCandidate[] = [];
  let covered = 0;
  let dismissed = 0;
  for (const candidate of found) {
    if (maskedInContext(candidate) || isMasked(candidate.value, matching)) covered += 1;
    else if (ignored.has(await fingerprint(candidate.value))) dismissed += 1;
    else candidates.push(candidate);
  }
  return { candidates, covered, ignored: dismissed };
}

