/**
 * Session counters for the status line and status file. Pure: every change
 * returns a new object, so register.ts can apply it with `update` on $.state.
 * Counts, kinds and positions only; never a value, placeholder or path.
 * The shapes are the state contract's, in types/index.d.ts.
 */
import type { RedactRestoreBlockInfo, RedactRestoreMetrics } from '../types/index.d.ts';

export type MaskSource = 'prompt' | 'context' | 'attachment' | 'systemPrompt' | 'conversation';

export type BlockInfo = RedactRestoreBlockInfo;
export type Metrics = RedactRestoreMetrics;

export function emptyMetrics(now: number, version = '', surface = ''): Metrics {
  return {
    startedAt: now,
    updatedAt: now,
    lastEvent: 'session.start',
    version,
    surface,
    occurrences: 0,
    bySource: {},
    lastTurnMasked: 0,
    restoredCalls: 0,
    restoredByTool: {},
    keptCalls: 0,
    deniedCalls: 0,
    audits: 0,
    blocked: 0,
    lastAuditBlocked: false,
    lastBlock: null,
    mediaWithheld: 0,
    promptsDropped: 0,
    hookErrors: {},
  };
}

function bump(counts: Readonly<Record<string, number>>, key: string, by = 1): Record<string, number> {
  return { ...counts, [key]: (counts[key] ?? 0) + by };
}

function touched(m: Metrics, event: string, now: number): Metrics {
  return { ...m, lastEvent: event, updatedAt: now };
}

/** A change to apply: `(metrics, now) => metrics`. */
export type MetricsChange = (m: Metrics, now: number) => Metrics;

export const metricsChange = {
  newTurn: (): MetricsChange => (m, now) => touched({ ...m, lastTurnMasked: 0 }, 'prompt.submit', now),
  masked:
    (source: MaskSource, count: number, event: string): MetricsChange =>
    (m, now) =>
      touched(
        {
          ...m,
          occurrences: m.occurrences + count,
          lastTurnMasked: m.lastTurnMasked + count,
          bySource: bump(m.bySource, source, count),
        },
        event,
        now,
      ),
  media:
    (count: number): MetricsChange =>
    (m, now) =>
      touched({ ...m, mediaWithheld: m.mediaWithheld + count }, 'session.append', now),
  promptDropped: (): MetricsChange => (m, now) =>
    touched({ ...m, promptsDropped: m.promptsDropped + 1 }, 'prompt.submit', now),
  tool:
    (tool: string, action: 'restore' | 'keep' | 'deny'): MetricsChange =>
    (m, now) =>
      touched(
        action === 'restore'
          ? { ...m, restoredCalls: m.restoredCalls + 1, restoredByTool: bump(m.restoredByTool, tool) }
          : action === 'keep'
            ? { ...m, keptCalls: m.keptCalls + 1 }
            : { ...m, deniedCalls: m.deniedCalls + 1 },
        'tool.call',
        now,
      ),
  audit:
    (block: BlockInfo | null): MetricsChange =>
    (m, now) =>
      touched(
        {
          ...m,
          audits: m.audits + 1,
          lastAuditBlocked: block !== null,
          blocked: m.blocked + (block ? 1 : 0),
          lastBlock: block ?? m.lastBlock,
        },
        'turn.step',
        now,
      ),
  hookError:
    (hook: string): MetricsChange =>
    (m, now) =>
      touched({ ...m, hookErrors: bump(m.hookErrors, hook) }, hook, now),
};

/** Applies several changes in order. */
export function combine(...changes: MetricsChange[]): MetricsChange {
  return (m, now) => changes.reduce((current, change) => change(current, now), m);
}

export type HealthState = 'ok' | 'warn' | 'blocked';

/** `blocked` while the last audited request was refused; `warn` on hook errors or rejected settings. */
export function healthState(m: Metrics, configProblems: number): HealthState {
  if (m.lastAuditBlocked) return 'blocked';
  const errors = Object.values(m.hookErrors).reduce((sum, n) => sum + n, 0);
  return errors > 0 || configProblems > 0 ? 'warn' : 'ok';
}

files.hooks/policy.ts:
/**
 * Which tools get original values back. Pure and data-driven: the defaults are
 * tables here, and every table can be replaced from plugin options.
 *
 * Threat model: only the model API must not see private values. Tools that run
 * on this machine get originals; tools that forward their input to a model
 * (subagents, WebFetch's summarizer, server-side search, other sessions) keep
 * placeholders, because no hook re-masks what they send. Built-in lists set
 * the floor; options only add to them.
 */
import { BUILTIN_KEEP_TOOLS, FILE_TOOLS } from './defaults.ts';
export type RestoreMode = 'all' | 'files' | 'none';

/** What happens to a tool call whose input holds placeholders. */
export type ToolAction = 'restore' | 'keep' | 'deny';

export interface RestorePolicy {
  readonly mode: RestoreMode;
  /** Extra tool name patterns that keep placeholders, on top of BUILTIN_KEEP_TOOLS. */
  readonly keepTools: readonly string[];
  /** Extra tool name patterns refused on placeholder text, on top of BUILTIN_DENY_UNRESTORED_TOOLS. */
  readonly denyUnrestoredTools: readonly string[];
}

export const RESTORE_MODES: readonly RestoreMode[] = ['all', 'files', 'none'];

export { BUILTIN_KEEP_TOOLS, FILE_TOOLS };

/** Placeholder text written into a file is silent data loss; always refused. */
export const BUILTIN_DENY_UNRESTORED_TOOLS: readonly string[] = FILE_TOOLS;

/** Options add to the built-in lists, so their defaults are empty. */
export const DEFAULT_POLICY: RestorePolicy = {
  mode: 'all',
  keepTools: [],
  denyUnrestoredTools: [],
};

/** `*` matches any run of characters; everything else is literal. */
export function matchesPattern(name: string, pattern: string): boolean {
  if (!pattern.includes('*')) return name === pattern;
  const source = pattern
    .split('*')
    .map(part => part.replace(/[.+?^${}()|[\]\\]/g, '\\$&'))
    .join('.*');
  return new RegExp(`^${source}$`).test(name);
}

function matchesAny(name: string, patterns: readonly string[]): boolean {
  return patterns.some(pattern => matchesPattern(name, pattern));
}

/** The action for a tool call that carries placeholders. */
export function keptTools(policy: RestorePolicy): readonly string[] {
  return [...new Set([...BUILTIN_KEEP_TOOLS, ...policy.keepTools])];
}

export function toolAction(tool: string, policy: RestorePolicy): ToolAction {
  if (matchesAny(tool, keptTools(policy))) return 'keep';
  const restores = policy.mode === 'all' || (policy.mode === 'files' && FILE_TOOLS.includes(tool));
  if (restores) return 'restore';
  const denied = [...BUILTIN_DENY_UNRESTORED_TOOLS, ...policy.denyUnrestoredTools];
  return matchesAny(tool, denied) ? 'deny' : 'keep';
}

/** Comma- or newline-separated patterns; blanks dropped. */
export function parsePatternList(raw: string): string[] {
  return raw
    .split(/[,\n]/)
    .map(item => item.trim())
    .filter(item => item.length > 0);
}

files.hooks/privacy.ts:
import { AUDIT_MEMO_LIMIT, MAX_INPUT_DEPTH, MESSAGES } from './defaults.ts';
import {
  findPrivateMatches,
  type KnownValue,
  type MatchingOptions,
  type PrivacyCategory,
  type PrivateMatch,
  textHash,
} from './matcher.ts';
import { CUSTOM_LABEL, DEFAULT_SCHEME, type PlaceholderScheme } from './placeholder.ts';

/** Side-effect-free matching and token restoration helpers.
 * No Claude Code $ API is imported or passed here: its static validator forbids
 * passing $ into functions imported from other local files.
 */
/**
 * Placeholder to original value. A vault is never changed in place: every
 * addition makes a new object, so lookups built from one can be cached by identity.
 */
export type Vault = Record<string, string>;

/** Placeholder to description ("client company name"), for the model; never a value. */
export type Notes = Record<string, string>;

export interface MaskResult {
  text: string;
  additions: Vault;
  /** Descriptions of new placeholders, from their rule or pattern. */
  notes: Notes;
  /** Replacements made, counting every occurrence. */
  count: number;
}

/** A block as the Messages API spells it; the engine's ApiContentBlock has this shape. */
export interface ContentBlock {
  readonly type: string;
  readonly [field: string]: unknown;
}

const MEDIA_TYPES = new Set(['image', 'document']);

export const WITHHELD_TEXT = MESSAGES.withheld;

export function withheldMediaText(type: string): string {
  return `[Withheld by Redact Restore: ${type} content cannot be scanned for private values]`;
}

function categoryOf(token: string, scheme: PlaceholderScheme): PrivacyCategory {
  return scheme.labelOf(token) ?? CUSTOM_LABEL;
}

export function knownValues(vault: Vault, scheme: PlaceholderScheme = DEFAULT_SCHEME): KnownValue[] {
  return [...vaultView(vault, scheme).known];
}

interface VaultView {
  readonly known: readonly KnownValue[];
  readonly tokens: readonly string[];
  /** Value to its placeholder. */
  readonly reverse: ReadonlyMap<string, string>;
}

// Built once per vault object and format: a large session masks many texts against one vault.
const vaultViews = new WeakMap<Vault, { readonly format: string; readonly view: VaultView }>();

function vaultView(vault: Vault, scheme: PlaceholderScheme): VaultView {
  const cached = vaultViews.get(vault);
  if (cached?.format === scheme.format) return cached.view;
  const entries = Object.entries(vault);
  const view: VaultView = {
    known: entries.map(([token, value]) => ({ value, category: categoryOf(token, scheme) })),
    tokens: entries.map(([token]) => token),
    reverse: new Map(entries.map(([token, value]) => [value, token])),
  };
  vaultViews.set(vault, { format: scheme.format, view });
  return view;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Known tokens restore exactly, whatever format minted them. A side that starts
// or ends with a word character gets a boundary, so an alias such as CODENAME_X
// is not restored inside CODENAME_X2.
let tokenCache: { vault: Vault; size: number; key: string; pattern: RegExp } | undefined;
function knownTokenPattern(vault: Vault, scheme: PlaceholderScheme = DEFAULT_SCHEME): RegExp | undefined {
  const tokens = Object.keys(vault);
  if (tokens.length === 0) return undefined;
  // A vault only grows and never remaps a token: the same object at the same size is unchanged.
  if (
    tokenCache?.vault === vault &&
    tokenCache.size === tokens.length &&
    tokenCache.key.startsWith(`${scheme.format}\u0001`)
  ) {
    tokenCache.pattern.lastIndex = 0;
    return tokenCache.pattern;
  }
  tokens.sort((a, b) => b.length - a.length);
  const key = `${scheme.format}\u0001${tokens.join('\u0000')}`;
  if (tokenCache?.key !== key) {
    const word = /[A-Za-z0-9_]/;
    // Placeholders restore wherever they appear; aliases only as whole words.
    const bounded = (token: string) => scheme.labelOf(token) === undefined;
    const source = tokens
      .map(
        token =>
          `${bounded(token) && word.test(token.charAt(0)) ? '(?<![A-Za-z0-9_])' : ''}` +
          escapeRegExp(token) +
          `${bounded(token) && word.test(token.charAt(token.length - 1)) ? '(?![A-Za-z0-9_])' : ''}`,
      )
      .join('|');
    tokenCache = { vault, size: tokens.length, key, pattern: new RegExp(source, 'g') };
  } else tokenCache = { ...tokenCache, vault, size: tokens.length };
  tokenCache.pattern.lastIndex = 0;
  return tokenCache.pattern;
}

/** Each private value in the text, once and in order, with its label: for a local preview, never for sending. */
export function uniqueMatches(
  text: string,
  options: MatchingOptions,
  vault: Vault,
): Array<{ label: string; value: string }> {
  const scheme = options.placeholders ?? DEFAULT_SCHEME;
  const seen = new Set<string>();
  const found: Array<{ label: string; value: string }> = [];
  const view = vaultView(vault, scheme);
  for (const match of findPrivateMatches(text, options, view.known, view.tokens)) {
    if (seen.has(match.value)) continue;
    seen.add(match.value);
    found.push({ label: options.rules?.get(match.value.toLowerCase())?.label ?? match.category, value: match.value });
  }
  return found;
}

export function maskText(text: string, options: MatchingOptions, vault: Vault): MaskResult {
  return maskAgainst(text, options, vault, NO_PENDING);
}

/**
 * Placeholders a masker minted for earlier texts, kept apart from the vault so
 * the vault's cached lookups stay valid. Their values are found again by the
 * same rules and detectors that found them first.
 */
interface Pending {
  readonly tokens: Vault;
  readonly byValue: ReadonlyMap<string, string>;
}
const NO_PENDING: Pending = { tokens: {}, byValue: new Map() };

function maskAgainst(text: string, options: MatchingOptions, vault: Vault, pending: Pending): MaskResult {
  const scheme = options.placeholders ?? DEFAULT_SCHEME;
  const view = vaultView(vault, scheme);
  const matches = findPrivateMatches(text, options, view.known, view.tokens);
  if (matches.length === 0) return { text, additions: {}, notes: {}, count: 0 };

  const reverse = view.reverse;
  // Values first masked in this text; the cached view stays as it was.
  const added = new Map<string, string>();
  const additions: Vault = {};
  const notes: Notes = {};
  const fragments: string[] = [];
  let last = 0;

  for (const match of matches) {
    let token = reverse.get(match.value) ?? pending.byValue.get(match.value) ?? added.get(match.value);
    if (!token) {
      const rule = options.rules?.get(match.value.toLowerCase());
      if (rule?.alias !== undefined) {
        // One alias per configured value; a case variant reuses it.
        token = rule.alias;
        if (vault[token] === undefined && pending.tokens[token] === undefined && additions[token] === undefined) {
          additions[token] = match.value;
          if (rule.description) notes[token] = rule.description;
        }
      } else {
        const label = rule?.label ?? match.category;
        token = scheme.make(label, match.value);
        // A stable id that another value already holds (a truncated-hash collision) falls back to random.
        const holder = vault[token] ?? pending.tokens[token] ?? additions[token];
        if (holder !== undefined && holder !== match.value) token = scheme.make(label);
        additions[token] = match.value;
        const description = rule?.description ?? match.description;
        if (description) notes[token] = description;
      }
      added.set(match.value, token);
    }
    fragments.push(text.slice(last, match.start), token);
    last = match.end;
  }
  fragments.push(text.slice(last));
  return { text: fragments.join(''), additions, notes, count: matches.length };
}

/** Placeholders of the active format in `text`, known or not. */
export function findPlaceholders(text: string, scheme: PlaceholderScheme = DEFAULT_SCHEME): string[] {
  return [...text.matchAll(scheme.pattern)].map(match => match[0]);
}

/**
 * Restores every known token (placeholders of any format, and aliases). With
 * `failOnUnknown`, a placeholder of the active format that the vault does not
 * know throws: a tool must not run on text that looks restored but is not.
 */
export function unmaskText(
  text: string,
  vault: Vault,
  failOnUnknown = false,
  scheme: PlaceholderScheme = DEFAULT_SCHEME,
): string {
  if (failOnUnknown && findPlaceholders(text, scheme).some(token => vault[token] === undefined)) {
    throw new Error('Cannot restore an unknown private placeholder');
  }
  const known = knownTokenPattern(vault, scheme);
  return known ? text.replace(known, token => vault[token] ?? token) : text;
}

/** Calls `visit` on every string inside plain objects and arrays, up to a depth cap. */
function mapStrings(value: unknown, visit: (text: string) => string, depth = 0): unknown {
  if (typeof value === 'string') return visit(value);
  if (depth >= MAX_INPUT_DEPTH || value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) {
    const mapped = value.map(item => mapStrings(item, visit, depth + 1));
    return mapped.some((item, index) => item !== value[index]) ? mapped : value;
  }
  if (Object.getPrototypeOf(value) !== Object.prototype) return value;
  let changed = false;
  const entries = Object.entries(value).map(([key, child]) => {
    const mapped = mapStrings(child, visit, depth + 1);
    if (mapped !== child) changed = true;
    return [key, mapped] as const;
  });
  return changed ? Object.fromEntries(entries) : value;
}

/** Whether any string inside a tool input holds a placeholder or a known alias. */
export function inputHasPlaceholder(
  input: unknown,
  vault: Vault = {},
  scheme: PlaceholderScheme = DEFAULT_SCHEME,
): boolean {
  const known = knownTokenPattern(vault, scheme);
  let found = false;
  mapStrings(input, text => {
    if (!found && (findPlaceholders(text, scheme).length > 0 || (known !== undefined && known.test(text))))
      found = true;
    if (known) known.lastIndex = 0;
    return text;
  });
  return found;
}

/**
 * Restores placeholders in every string of a tool input, keys untouched.
 * Unknown placeholders throw: a tool must not run on text that looks restored
 * but is not. Returns the same object when nothing changed.
 */
export function restoreInput<T>(input: T, vault: Vault, scheme: PlaceholderScheme = DEFAULT_SCHEME): T {
  return mapStrings(input, text => unmaskText(text, vault, true, scheme)) as T;
}

/**
 * Restores known tokens in every string of a value, for drawing on this
 * machine only. Unknown placeholders stay as they are. Returns the same value
 * when nothing changed.
 */
export function restoreForDisplay<T>(value: T, vault: Vault, scheme: PlaceholderScheme = DEFAULT_SCHEME): T {
  return mapStrings(value, text => unmaskText(text, vault, false, scheme)) as T;
}

/**
 * The props with the named fields restored for display; the same object when
 * nothing changed, and a field that was absent stays absent.
 */
export function restoreFields<T extends object>(
  props: T,
  fields: readonly string[],
  vault: Vault,
  scheme: PlaceholderScheme = DEFAULT_SCHEME,
): T {
  let changed: Record<string, unknown> | undefined;
  for (const field of fields) {
    if (!(field in props)) continue;
    const value = (props as Record<string, unknown>)[field];
    const restored = restoreForDisplay(value, vault, scheme);
    if (restored !== value) changed = { ...changed, [field]: restored };
  }
  return changed ? { ...props, ...changed } : props;
}

/**
 * Restores placeholders in streamed text, one buffer per content block. A tail
 * that may be the start of a placeholder waits for the next piece, so a token
 * split across chunks is still restored; `flush` releases what is left.
 */
export function createStreamRestorer(vault: Vault, scheme: PlaceholderScheme = DEFAULT_SCHEME) {
  const held = new Map<number, string>();
  return {
    push(index: number, text: string): string {
      const combined = (held.get(index) ?? '') + text;
      const cut = scheme.holdPoint(combined);
      held.set(index, combined.slice(cut));
      return unmaskText(combined.slice(0, cut), vault, false, scheme);
    },
    flush(index: number): string {
      const rest = held.get(index) ?? '';
      held.delete(index);
      return unmaskText(rest, vault, false, scheme);
    },
    /** Blocks that still hold text, in the order they started. */
    pending(): number[] {
      return [...held].filter(([, text]) => text.length > 0).map(([index]) => index);
    },
  };
}

/** Masks several strings against one evolving vault, collecting new mappings. */
export function createMasker(options: MatchingOptions, vault: Vault) {
  const additions: Vault = {};
  const byValue = new Map<string, string>();
  const pending: Pending = { tokens: additions, byValue };
  const notes: Notes = {};
  let count = 0;
  return {
    mask(text: string): string {
      const masked = maskAgainst(text, options, vault, pending);
      for (const [token, value] of Object.entries(masked.additions)) {
        additions[token] = value;
        byValue.set(value, token);
      }
      Object.assign(notes, masked.notes);
      count += masked.count;
      return masked.text;
    },
    additions: (): Vault => additions,
    notes: (): Notes => notes,
    count: (): number => count,
  };
}

export interface BlockPolicy {
  /** Keep image/document blocks (which cannot be scanned) instead of withholding them. */
  readonly allowMedia: boolean;
}

export interface MaskBlocksResult<T> {
  content: T[];
  additions: Vault;
  notes: Notes;
  withheldMedia: number;
  /** Replacements made, counting every occurrence. */
  count: number;
}

/** Scan conversation content blocks without mutating the input.
 *
 * Covers text blocks and tool_result content (string, or nested text/media
 * items). Media blocks are replaced by a text notice unless the policy allows
 * them. Every other kind (tool_use, thinking, server tool blocks) is returned
 * as-is: Claude Code pins those blocks in `session.append` and puts back any
 * rewrite, so masking them here would only give a false sense of coverage.
 */
export function maskContentBlocks<T extends ContentBlock>(
  blocks: readonly T[],
  options: MatchingOptions,
  vault: Vault,
  policy: BlockPolicy,
): MaskBlocksResult<T> {
  const masker = createMasker(options, vault);
  let withheldMedia = 0;

  const maskItem = (item: unknown): unknown => {
    if (!item || typeof item !== 'object' || !('type' in item)) return item;
    const block = item as ContentBlock;
    if (block.type === 'text' && typeof block.text === 'string') {
      return { ...block, text: masker.mask(block.text) };
    }
    if (MEDIA_TYPES.has(block.type) && !policy.allowMedia) {
      withheldMedia += 1;
      return { type: 'text', text: withheldMediaText(block.type) };
    }
    return item;
  };

  const content = blocks.map((block): T => {
    if (block.type === 'text' || MEDIA_TYPES.has(block.type)) return maskItem(block) as T;
    if (block.type === 'tool_result') {
      if (typeof block.content === 'string') {
        return { ...block, content: masker.mask(block.content) };
      }
      if (Array.isArray(block.content)) {
        return { ...block, content: block.content.map(maskItem) };
      }
    }
    return block;
  });

  return { content, additions: masker.additions(), notes: masker.notes(), withheldMedia, count: masker.count() };
}

/** Replacement content when scanning failed: no text, tool result or media survives. */
export function withholdContentBlocks<T extends ContentBlock>(blocks: readonly T[]): T[] {
  return blocks.map((block): T => {
    if (block.type === 'text') return { ...block, text: WITHHELD_TEXT };
    if (block.type === 'tool_result') return { ...block, content: WITHHELD_TEXT };
    if (MEDIA_TYPES.has(block.type)) return { type: 'text', text: WITHHELD_TEXT } as unknown as T;
    return block;
  });
}

export interface AuditFinding {
  readonly messageIndex: number;
  /** The block kind the finding sits in (`text`, `tool_result`, `image`...), never its content. */
  readonly blockType: string;
  /** The detector label (`EMAIL`, `AWS_KEY`, `CUSTOM`, ...) or `MEDIA`. */
  readonly reason: string;
}

/** The parts of a user-role message that carry text the model has not authored. */
function* userTexts(block: ContentBlock): Generator<string | { media: string }> {
  if (block.type === 'text' && typeof block.text === 'string') yield block.text;
  else if (MEDIA_TYPES.has(block.type)) yield { media: block.type };
  else if (block.type === 'tool_result') {
    if (typeof block.content === 'string') yield block.content;
    else if (Array.isArray(block.content)) {
      for (const item of block.content) {
        if (item && typeof item === 'object' && 'type' in item) yield* userTexts(item as ContentBlock);
      }
    }
  }
}

/**
 * Engine attachments (environment, mentioned files, files re-attached after
 * compaction, reminders) arrive as `<system-reminder>` text blocks. Every
 * request re-renders them through `prompt.attachment`, which masks them after
 * this audit runs, while `$.session.messages()` can hold their raw copy (after
 * compaction, and in subagents). The audit leaves them to that hook.
 */
const SYSTEM_REMINDER = /^\s*<system-reminder>/;

/**
 * Pre-send audit of a request's messages. Scans only user-role content: the
 * assistant's text and tool calls were written by the model, so sending them
 * back discloses nothing it has not already seen. Returns no values, only where
 * and which kind of detector fired.
 */
/**
 * What an audit remembers between requests: text it found clean, and how many
 * vault entries existed then. A long conversation is resent whole on every
 * request; with the memo only new text gets the full scan, and old text is
 * checked only for values the vault learned since. Keep one memo per matching
 * options object: new rules or detectors need a full scan.
 */
export interface AuditMemo {
  readonly clean: Map<string, number>;
}

export function createAuditMemo(): AuditMemo {
  return { clean: new Map() };
}

/** Options that match only known values: for re-checking clean text against values learned since. */
function knownOnly(options: MatchingOptions): MatchingOptions {
  return {
    customValues: [],
    customCaseInsensitive: false,
    redactEmails: false,
    detectors: [],
    ...(options.placeholders ? { placeholders: options.placeholders } : {}),
  };
}

export function auditMessages(
  messages: ReadonlyArray<{ readonly role: string; readonly content: readonly ContentBlock[] }>,
  options: MatchingOptions,
  vault: Vault,
  policy: BlockPolicy,
  memo?: AuditMemo,
): AuditFinding[] {
  const { known, tokens } = vaultView(vault, options.placeholders ?? DEFAULT_SCHEME);
  const findings: AuditFinding[] = [];
  const recheck = knownOnly(options);
  // The first match in a part, scanning only what the memo has not seen yet.
  const firstMatch = (part: string): PrivateMatch | undefined => {
    if (!memo) return findPrivateMatches(part, options, known, tokens)[0];
    const key = textHash(part);
    const seenAt = memo.clean.get(key);
    if (seenAt === tokens.length) return undefined;
    const match =
      seenAt === undefined
        ? findPrivateMatches(part, options, known, tokens)[0]
        : findPrivateMatches(part, recheck, known.slice(seenAt), tokens)[0];
    if (!match) {
      if (memo.clean.size >= AUDIT_MEMO_LIMIT) memo.clean.clear();
      memo.clean.set(key, tokens.length);
    }
    return match;
  };
  messages.forEach((message, messageIndex) => {
    if (message.role !== 'user') return;
    for (const block of message.content) {
      if (block.type === 'text' && typeof block.text === 'string' && SYSTEM_REMINDER.test(block.text)) continue;
      for (const part of userTexts(block)) {
        if (typeof part !== 'string') {
          if (!policy.allowMedia) findings.push({ messageIndex, blockType: block.type, reason: 'MEDIA' });
          continue;
        }
        const first = firstMatch(part);
        if (first) findings.push({ messageIndex, blockType: block.type, reason: first.category });
      }
    }
  });
  return findings;
}

/** Counts and locations only; never a value. */
export function describeFindings(findings: readonly AuditFinding[]): string {
  const counts = new Map<string, number>();
  for (const finding of findings) {
    const key = `${finding.reason.toLowerCase()} in message ${finding.messageIndex} ${finding.blockType}`;
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return [...counts].map(([key, count]) => `${count} ${key}`).join(', ');
}

/**
 * The note for the model that says what new placeholders stand for: one line
 * per placeholder, in the order given, at most `limit` of them. Descriptions
 * pass through `mask` first, so a description that names another private value
 * carries that value's placeholder. Never holds a value.
 */
export function legendText(
  entries: ReadonlyArray<readonly [token: string, description: string]>,
  header: string,
  mask: (text: string) => string,
): string {
  return [header, ...entries.map(([token, description]) => `- ${token}: ${mask(description)}`)].join('\n');
}

files.hooks/detectors.ts:
/**
 * Built-in detectors: one table, each entry an id, a label for its
 * placeholders, groups for configuration, and a finder that returns spans.
 * Pure and linear-time (prefix-anchored, bounded quantifiers, a literal hint
 * checked first). Validators (checksums, entropy, decoders) keep false
 * positives down; a detector masks only the secret part of what it matches.
 *
 * Sources of the rules: gitleaks and claude-code-redact (provider keys, JWT,
 * PEM, connection strings, assignments), maskit (Chinese ID, mobile, USCC,
 * Chinese assignment keywords), Presidio (Luhn, IBAN).
 */
import {
  GENERIC_INTERNAL_HOST,
  INTERNAL_HOST,
  KEYWORD_RESCAN_LIMIT,
  KEYWORD_WINDOW_AFTER,
  KEYWORD_WINDOW_BEFORE,
  MIN_CUSTOM_VALUE_LENGTH,
  TRIVIAL_VALUE,
} from './defaults.ts';
import { GITLEAKS_ALLOW, GITLEAKS_RULES, GITLEAKS_STOPWORDS, type GitleaksRule } from './vendor/gitleaks-rules.ts';

export interface Span {
  readonly start: number;
  readonly end: number;
  /** Overrides the detector's label (a table detector such as gitleaks labels per rule). */
  readonly label?: string;
}

export type DetectorGroup = 'secrets' | 'pii' | 'cn' | 'network' | 'gitleaks';

export interface Detector {
  readonly id: string;
  readonly label: string;
  readonly groups: readonly DetectorGroup[];
  readonly defaultOn: boolean;
  /** Labels this detector beats where their spans overlap (e.g. a password over an email). */
  readonly outranks?: readonly string[];
  /** Tie-break against other matches of the same span: lower wins (built-ins 1, gitleaks 2). */
  readonly rank?: number;
  /** What a match is, told to the model with its placeholder (pattern rules). */
  readonly description?: string;
  find(text: string): Span[];
}

/** Spans of a regex's `secret` named group (or the whole match), filtered by `accept`. */
function spans(
  pattern: RegExp,
  text: string,
  accept: (value: string, match: RegExpExecArray) => boolean = () => true,
): Span[] {
  const found: Span[] = [];
  pattern.lastIndex = 0;
  for (let match = pattern.exec(text); match; match = pattern.exec(text)) {
    const secret = match.groups?.secret;
    const value = secret ?? match[0];
    const offset = secret === undefined ? 0 : match[0].lastIndexOf(secret);
    if (value && accept(value, match))
      found.push({ start: match.index + offset, end: match.index + offset + value.length });
    if (match[0].length === 0) pattern.lastIndex += 1;
  }
  return found;
}

// `KEY=value` with an upper-case key: a whole line (as in .env files, where
// spaces around `=` and a value running to the end of the line are allowed),
// or inline with no spaces around `=` (`FOO=bar cmd`, a one-line paste).
const ENV_LINE = /^[ \t]*(?:export[ \t]+)?([A-Z][A-Z0-9_]{1,63})[ \t]*=[ \t]*([^\r\n]*)$/gm;
const ENV_INLINE = /(?<![\w.$-])([A-Z][A-Z0-9_]{1,63})=("[^"\r\n]*"|'[^'\r\n]*'|[^\s"'`;,|&)]+)/g;

/** A value worth hiding: not empty, trivial (`true`, `8080`), a reference (`${HOME}`) or a placeholder. */
function envValueWorthMasking(value: string): boolean {
  return (
    value.length >= MIN_CUSTOM_VALUE_LENGTH &&
    !TRIVIAL_VALUE.test(value) &&
    // Code, not configuration: a call (`getLogger(__name__)`) or a comparison (`MODE==X`).
    !/[()]/.test(value) &&
    !value.startsWith('=') &&
    !/^\$\{?[A-Za-z_]/.test(value) &&
    !value.includes('{{') &&
    !/^<[^>]*>$/.test(value)
  );
}

/** The value's span inside a raw `=` right-hand side: quotes and a trailing comment removed. */
function valueSpan(text: string, rawStart: number, raw: string, comments: boolean): { start: number; end: number } {
  const quote = raw.charAt(0);
  const close = quote === '"' || quote === "'" ? raw.indexOf(quote, 1) : -1;
  if (close > 0) return { start: rawStart + 1, end: rawStart + close };
  let end = rawStart + raw.length;
  const comment = comments ? raw.search(/\s#/) : -1;
  if (comment >= 0) end = rawStart + comment;
  while (end > rawStart && /\s/.test(text.charAt(end - 1))) end -= 1;
  // An unquoted value stops at whitespace: `NODE_ENV=production bun run build` masks one word.
  const space = text.slice(rawStart, end).search(/\s/);
  if (space >= 0) end = rawStart + space;
  return { start: rawStart, end };
}

/**
 * Every `KEY=value` assignment's value, quotes and trailing comments removed:
 * the env detector masks them, and a path scan lists them.
 */
export function envAssignments(text: string): Array<{ key: string; value: string; start: number; end: number }> {
  if (!text.includes('=')) return [];
  const found: Array<{ key: string; value: string; start: number; end: number }> = [];
  // Whole-line spans, in text order; an inline match inside one is skipped. Both
  // lists run forward, so one pointer checks overlap in linear time.
  const lines: Array<{ start: number; end: number }> = [];
  ENV_LINE.lastIndex = 0;
  for (let match = ENV_LINE.exec(text); match; match = ENV_LINE.exec(text)) {
    const raw = match[2] ?? '';
    const span = valueSpan(text, match.index + match[0].length - raw.length, raw, true);
    const value = text.slice(span.start, span.end);
    if (!envValueWorthMasking(value)) continue;
    lines.push(span);
    found.push({ key: match[1] ?? '', value, ...span });
  }
  let line = 0;
  ENV_INLINE.lastIndex = 0;
  for (let match = ENV_INLINE.exec(text); match; match = ENV_INLINE.exec(text)) {
    const raw = match[2] ?? '';
    const span = valueSpan(text, match.index + match[0].length - raw.length, raw, false);
    while (line < lines.length && (lines[line]?.end ?? 0) <= span.start) line += 1;
    if (line < lines.length && (lines[line]?.start ?? Infinity) < span.end) continue;
    const value = text.slice(span.start, span.end);
    if (envValueWorthMasking(value)) found.push({ key: match[1] ?? '', value, ...span });
  }
  return found.sort((a, b) => a.start - b.start);
}

/**
 * Host names on private networks, told apart from code such as `self.local` or
 * `threading.local()`: three or more labels, a digit or hyphen in the first label,
 * or a host context (`//host`, `@host`, `host:port`); never a call.
 */
export function findInternalHosts(text: string): Span[] {
  const spans: Span[] = [];
  INTERNAL_HOST.lastIndex = 0;
  for (const match of text.matchAll(INTERNAL_HOST)) {
    const value = match[0];
    const start = match.index;
    const end = start + value.length;
    if (GENERIC_INTERNAL_HOST.test(value) || text.charAt(end) === '(') continue;
    const labels = value.split('.');
    const hostLike =
      labels.length >= 3 ||
      /[\d-]/.test(labels[0] ?? '') ||
      /(?:\/\/|@)$/.test(text.slice(Math.max(0, start - 2), start)) ||
      /^:\d/.test(text.slice(end, end + 2));
    if (hostLike) spans.push({ start, end });
  }
  return spans;
}

/** A detector from a regex, with an optional literal hint that must appear first. */
function regexDetector(
  id: string,
  label: string,
  groups: readonly DetectorGroup[],
  defaultOn: boolean,
  pattern: RegExp,
  hint?: string | readonly string[],
  accept?: (value: string, match: RegExpExecArray) => boolean,
): Detector {
  const hints = hint === undefined ? [] : typeof hint === 'string' ? [hint] : hint;
  return {
    id,
    label,
    groups,
    defaultOn,
    find: text => (hints.length > 0 && !hints.some(h => text.includes(h)) ? [] : spans(pattern, text, accept)),
  };
}

// --- validators -----------------------------------------------------------

/** Rejects documentation fillers such as ghp_xxxxxxxx or AKIA...EXAMPLE. */
function looksReal(value: string): boolean {
  return new Set(value).size >= 6 && !/EXAMPLE|example|x{6,}|X{6,}|\*{3,}/.test(value);
}

export function shannonEntropy(value: string): number {
  const counts = new Map<string, number>();
  for (const char of value) counts.set(char, (counts.get(char) ?? 0) + 1);
  let entropy = 0;
  for (const count of counts.values()) {
    const p = count / value.length;
    entropy -= p * Math.log2(p);
  }
  return entropy;
}

export function luhnValid(digits: string): boolean {
  let sum = 0;
  for (let i = 0; i < digits.length; i += 1) {
    let digit = Number(digits[digits.length - 1 - i]);
    if (i % 2 === 1) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    sum += digit;
  }
  return digits.length >= 13 && sum % 10 === 0;
}

const CN_ID_WEIGHTS = [7, 9, 10, 5, 8, 4, 2, 1, 6, 3, 7, 9, 10, 5, 8, 4, 2];
const CN_ID_CHECK = '10X98765432';
const CN_PROVINCES = new Set([
  11, 12, 13, 14, 15, 21, 22, 23, 31, 32, 33, 34, 35, 36, 37, 41, 42, 43, 44, 45, 46, 50, 51, 52, 53, 54, 61, 62, 63,
  64, 65, 71, 81, 82, 83, 91,
]);

/** 18-digit resident identity number: province code, real birth date, ISO 7064 check digit. */
export function cnIdValid(id: string): boolean {
  if (!/^\d{17}[\dXx]$/.test(id) || !CN_PROVINCES.has(Number(id.slice(0, 2)))) return false;
  const year = Number(id.slice(6, 10));
  const month = Number(id.slice(10, 12));
  const day = Number(id.slice(12, 14));
  const date = new Date(Date.UTC(year, month - 1, day));
  if (year < 1880 || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day || date.getTime() > Date.now()) {
    return false;
  }
  const sum = CN_ID_WEIGHTS.reduce((total, weight, index) => total + weight * Number(id[index]), 0);
  return CN_ID_CHECK[sum % 11] === id.charAt(17).toUpperCase();
}

const USCC_CHARS = '0123456789ABCDEFGHJKLMNPQRTUWXY';
const USCC_WEIGHTS = [1, 3, 9, 27, 19, 26, 16, 17, 20, 29, 25, 13, 8, 24, 10, 30, 28];

/** Unified social credit code (统一社会信用代码), GB 32100 MOD 31 check. */
export function usccValid(code: string): boolean {
  if (!/^[0-9A-HJ-NPQRTUWXY]{2}\d{6}[0-9A-HJ-NPQRTUWXY]{10}$/.test(code)) return false;
  const sum = USCC_WEIGHTS.reduce((total, weight, index) => total + weight * USCC_CHARS.indexOf(code.charAt(index)), 0);
  return USCC_CHARS.charAt((31 - (sum % 31)) % 31) === code.charAt(17);
}

/** ISO 13616 IBAN, spaces allowed: rearrange, letters to numbers, mod 97 == 1. */
export function ibanValid(raw: string): boolean {
  const iban = raw.replace(/ /g, '');
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(iban)) return false;
  const rearranged = iban.slice(4) + iban.slice(0, 4);
  let remainder = 0;
  for (const char of rearranged) {
    const value = /\d/.test(char) ? char : String(char.charCodeAt(0) - 55);
    for (const digit of value) remainder = (remainder * 10 + Number(digit)) % 97;
  }
  return remainder === 1;
}

/** A JWT whose header decodes to JSON with an `alg`. */
function jwtValid(token: string): boolean {
  try {
    const header = token.split('.')[0] ?? '';
    const json = atob(
      header
        .replace(/-/g, '+')
        .replace(/_/g, '/')
        .padEnd(Math.ceil(header.length / 4) * 4, '='),
    );
    const parsed: unknown = JSON.parse(json);
    return typeof parsed === 'object' && parsed !== null && 'alg' in parsed;
  } catch {
    return false;
  }
}

const SECRET_STOPWORDS =
  /^(?:changeme|change_me|password|passwd|secret|token|example|sample|dummy|placeholder|null|none|nil|true|false|undefined|redacted|xxx+|\*+|<[^>]*>|test|testing)$/i;

/** A credential value, not code or a template: no env refs, identifiers or member chains. */
function credentialValue(value: string, minEntropy: number): boolean {
  if (value.length < 8 || value.length > 16_384) return false;
  if (SECRET_STOPWORDS.test(value)) return false;
  if (/\$\{|\{\{|%\(|process\.env|os\.environ|getenv|^\$[A-Z_]/.test(value)) return false;
  if (/^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*(?:\(\))?$/.test(value) && !/\d/.test(value)) return false;
  // Code, not a credential: a call or a member chain (`request.headers.get(`, `cfg.db.pass`).
  if (
    /^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*\(/.test(value) ||
    /^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*){2,}$/.test(value)
  ) {
    return false;
  }
  if (!/[\d\W_]/.test(value)) return false;
  return shannonEntropy(value) >= minEntropy && looksReal(value);
}

// --- special finders ------------------------------------------------------

/** PEM private key blocks; a key cut off before its END line is masked to its last base64 line. */
function findPrivateKeys(text: string): Span[] {
  const found: Span[] = [];
  const begin = /-----BEGIN [A-Z0-9 ]{0,40}PRIVATE KEY(?: BLOCK)?-----/g;
  for (let match = begin.exec(text); match; match = begin.exec(text)) {
    const end = /-----END [A-Z0-9 ]{0,40}PRIVATE KEY(?: BLOCK)?-----/g;
    end.lastIndex = begin.lastIndex;
    const closing = end.exec(text);
    const limit = match.index + 16_384;
    let stop: number;
    if (closing && closing.index < limit) {
      stop = closing.index + closing[0].length;
    } else {
      stop = begin.lastIndex;
      // Real or JSON-escaped line breaks (a service-account key cut off mid-string).
      const body = /(?:\r?\n|(?:\\r)?\\n)[A-Za-z0-9+/=:\- ]{1,200}(?=\r?\n|(?:\\r)?\\n|$|["',])/y;
      body.lastIndex = stop;
      for (let line = body.exec(text); line && body.lastIndex <= limit; line = body.exec(text)) stop = body.lastIndex;
    }
    found.push({ start: match.index, end: stop });
    begin.lastIndex = stop;
  }
  return found;
}

/** Card numbers: 13-19 digits, one consistent separator, issuer prefix 2-6, Luhn. */
function findCards(text: string): Span[] {
  return spans(
    /(?<![\d.])[2-6]\d{3}(?<sep>[ -]?)\d{4}\k<sep>\d{4}\k<sep>\d{1,4}(?:\k<sep>\d{1,3})?(?![\d.])/g,
    text,
    value => luhnValid(value.replace(/[ -]/g, '')) && value.replace(/[ -]/g, '').length <= 19,
  );
}

