/**
 * Synchronous HMAC-SHA-256 (RFC 2104 over FIPS 180-4), pure. Masking runs
 * synchronously, and Web Crypto is async only, so stable placeholder ids use
 * this. Not for secrets at rest: it derives short ids from a local key.
 */

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98,
