    },
    "enable_detectors": {
      "type": "string",
      "title": "Extra detectors",
      "description": "Comma-separated detector ids or groups to turn on besides the defaults, e.g. gitleaks.generic-api-key, or groups gitleaks, all. Most detectors, including ipv4, phone and us_ssn, are on by default.",
      "default": ""
    },
    "disable_detectors": {
      "type": "string",
      "title": "Disabled detectors",
      "description": "Comma-separated detector ids or groups to turn off, e.g. ipv4, phone, us_ssn, cn_phone, secret_assignment, groups network, pii, cn, gitleaks (all 212 rules), or gitleaks.<rule-id>. Wins over Extra detectors.",
      "default": ""
    },
    "placeholder_format": {
      "type": "string",
      "title": "Placeholder format",
      "description": "How placeholders look. Default {{PRIVATE:{label}#{id}}}, e.g. {{PRIVATE:EMAIL#3fa1c09e8b2d}}. Must contain {id} once, may contain {label}, start with literal text, have no whitespace, and separate {label} and {id}. Alternatives: {{{label}_{id}}}, PRIVATE_{label}_{id} (identifier style, safe unquoted in YAML and templates), <<{label}:{id}>>.",
      "default": "{{PRIVATE:{label}#{id}}}"
    },
    "placeholder_id_length": {
      "type": "number",
      "title": "Placeholder id length",
      "description": "Random hex characters per placeholder, 8 to 32. Default 12 keeps placeholders short and unique within a session.",
      "default": 12
    },
    "placeholder_ids": {
      "type": "string",
      "title": "Placeholder ids across sessions",
      "description": "random: a value gets a new placeholder in each session. stable: the same value gets the same placeholder in every session (derived from a key kept in the plugin store on this machine), so the provider can tell that two sessions mention the same value, though not what it is.",
      "options": [
        "random",
        "stable"
      ],
      "default": "random"
    },
    "restore_display": {
      "type": "boolean",
      "title": "Restore local message display",
